/// dc10-store-destroy: a member's clone holding a backup is not destroyed by
/// `member remove --delete`, which names `rwv backup list` and refuses; the
/// operator's `backup drop` is what releases the commits.
pub fn dc10_store_destroy() -> Scenario {
    let app = Repo::App.rel_path();
    scenario(
        "dc10: a clone holding a backup is not destroyed",
        vec![
            create("anon"),
            Step::commit(&ww("anon"), Repo::App, "anon-app"),
            Step::rwv(
                &a(),
                &[
                    "workweave",
                    "delete",
                    "--project",
                    "proj",
                    "anon",
                    "--discard-unlanded",
                ],
            )
            .expect(Exit::Succeeds)
            .claim(Claim::BackedUp {
                repo: Repo::App,
                mark: "anon-app",
                marked: None,
            }),
            Step::rwv(
                &a(),
                &["member", "remove", &app, "--delete", "--project", "proj"],
            )
            .expect(Exit::refuses_kind(RefusalKind::DroppedRepoHasUniqueCommits))
            .claim(Claim::OutputContains("rwv backup list"))
            .claim(Claim::BackedUp {
                repo: Repo::App,
                mark: "anon-app",
                marked: None,
            }),
            Step::rwv(
                &a(),
                &["backup", "drop", &app, "--all", "--project", "proj"],
            )
            .expect(Exit::Succeeds)
            .may_strand(&[Repo::App]),
            Step::rwv(
                &a(),
                &["member", "remove", &app, "--delete", "--project", "proj"],
            )
            .expect(Exit::Succeeds)
            .claim(Claim::DirGone(Machine::A, "weave/local/remotes/app")),
        ],
    )
}

/// A member's clone in the primary is its repo's only store: removing it
/// removes edits the VCS set aside there. The dirty refusal of `member remove
/// --delete` does not offer to set the edits aside, and once they are set
/// aside anyway the removal refuses, naming them.
pub fn store_removal_refuses_edits_set_aside() -> Scenario {
    scenario(
        "a store removal refuses edits set aside",
        vec![
            Step::hand_edit(&a(), Repo::App, "README", "app", "hours of work"),
            Step::rwv(&a(), &["member", "remove", APP, "--delete"])
                .expect(Exit::refuses(Repo::App, State::EditsDirty))
                .claim(Claim::OutputLacks("stash"))
                .claim(Claim::OutputContains(" commit")),
            Step::git(&a(), Repo::App, &["stash", "push"]),
            Step::rwv(&a(), &["member", "remove", APP, "--delete"])
                .expect(Exit::refuses_kind(RefusalKind::DroppedRepoHasUniqueCommits))
                .claim(Claim::OutputContains("edits set aside"))
                .claim(Claim::DirStands(Machine::A, "weave/local/remotes/app")),
            Step::git(&a(), Repo::App, &["stash", "pop"]).may_strand(&[Repo::App]),
            Step::git(&a(), Repo::App, &["commit", "-qam", "kept"]),
            Step::rwv(&a(), &["member", "remove", APP, "--delete"])
                .expect(Exit::refuses_kind(RefusalKind::DroppedRepoHasUniqueCommits))
                .claim(Claim::OutputContains("branch main"))
                .claim(Claim::DirStands(Machine::A, "weave/local/remotes/app")),
        ],
    )
}

/// A landing that drops a member prunes the target's clone of it only when
/// that store holds nothing no remote has: edits set aside there, or a commit
/// only a tag holds, refuse the prune and leave the clone.
pub fn landing_prune_refuses_a_store_holding(held: StoreHolds) -> Scenario {
    let mut steps = vec![create("w")];
    steps.extend(match held {
        StoreHolds::SetAsideEdits => vec![
            Step::hand_edit(&a(), Repo::App, "README", "app", "hours of work"),
            Step::git(&a(), Repo::App, &["stash", "push"]),
        ],
        StoreHolds::TaggedCommit => vec![
            Step::commit(&a(), Repo::App, "tagged-only"),
            Step::git(&a(), Repo::App, &["tag", "keepme"]),
            Step::git(&a(), Repo::App, &["reset", "-q", "--hard", "HEAD~1"])
                .may_rewrite(&[Repo::App]),
        ],
    });
    steps.extend([
        Step::rwv(&ww("w"), &["member", "remove", APP, "--delete"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &["land", "--allow-member-change", APP])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputContains(
                "local/remotes/app: prune in the target's workspace skipped",
            ))
            .claim(Claim::OutputContains(match held {
                StoreHolds::SetAsideEdits => "edits set aside",
                StoreHolds::TaggedCommit => "tag keepme",
            }))
            .claim(Claim::DirStands(Machine::A, "weave/local/remotes/app")),
    ]);
    scenario(
        "a landing's prune refuses a store holding what no remote has",
        steps,
    )
}

/// A clone holding the only copy of a commit in a savepoint no operation
/// holds refuses its removal naming `rwv doctor --fix`, which keeps it as a
/// backup; the backup's drop it then prints runs as printed, and the removal
/// goes through.
pub fn store_removal_offers_an_exit_for_a_savepoint_it_holds() -> Scenario {
    scenario(
        "a store removal offers an exit for a savepoint it holds",
        vec![
            Step::commit(&a(), Repo::App, "savepoint-only"),
            Step::git(
                &a(),
                Repo::App,
                &["update-ref", "refs/rwv/pre-op/1779769917405921588", "HEAD"],
            ),
            Step::git(&a(), Repo::App, &["reset", "-q", "--hard", "HEAD~1"])
                .may_rewrite(&[Repo::App]),
            Step::rwv(&a(), &["member", "remove", APP, "--delete"])
                .expect(Exit::refuses_kind(RefusalKind::DroppedRepoHasUniqueCommits))
                .claim(Claim::OutputContains("(`rwv doctor --fix`)"))
                .claim(Claim::DirStands(Machine::A, "weave/local/remotes/app")),
            Step::rwv_printed_quoted(&a(), "rwv doctor --fix", "").expect(Exit::Succeeds),
            Step::rwv(&a(), &["member", "remove", APP, "--delete"])
                .expect(Exit::refuses_kind(RefusalKind::DroppedRepoHasUniqueCommits))
                .claim(Claim::OutputContains("rwv backup drop local/remotes/app ")),
            Step::rwv_printed_quoted(&a(), "rwv backup drop ", "")
                .expect(Exit::Succeeds)
                .may_strand(&[Repo::App]),
            Step::rwv(&a(), &["member", "remove", APP, "--delete"])
                .expect(Exit::Succeeds)
                .claim(Claim::DirGone(Machine::A, "weave/local/remotes/app")),
        ],
    )
}

/// A landing's prune of the target's clone asks each submodule store inside
/// it what it holds that no remote has, and names it with the submodule's
/// path; the per-path removal the landing prints refuses the same way until
/// it is let go.
pub fn landing_prune_asks_a_submodule_store_inside_the_clone() -> Scenario {
    let file = "protocol.file.allow=always";
    scenario(
        "a landing's prune asks a submodule store inside the clone",
        vec![
            create("w"),
            Step::git(
                &a(),
                Repo::App,
                &["-c", file, "submodule", "add", "-q", "../lib.git", "sub"],
            ),
            Step::git(&a(), Repo::App, &["commit", "-qm", "add sub"]),
            Step::git(&a(), Repo::App, &["push", "-q", "origin", "main"])
                .pushes(Remote::origin(Repo::App), "main"),
            Step::git(
                &a(),
                Repo::App,
                &[
                    "-C",
                    "sub",
                    "commit",
                    "-q",
                    "--allow-empty",
                    "-m",
                    "side-only",
                ],
            ),
            Step::git(&a(), Repo::App, &["-C", "sub", "branch", "side"]),
            Step::git(
                &a(),
                Repo::App,
                &["-C", "sub", "reset", "-q", "--hard", "HEAD~1"],
            ),
            Step::rwv(&ww("w"), &["member", "remove", APP, "--delete"]).expect(Exit::Succeeds),
            Step::rwv(&ww("w"), &["land", "--allow-member-change", APP])
                .expect(Exit::Succeeds)
                .claim(Claim::OutputContains(
                    "local/remotes/app: prune in the target's workspace skipped",
                ))
                .claim(Claim::OutputContains("branch side in submodule sub"))
                .claim(Claim::DirStands(Machine::A, "weave/local/remotes/app")),
            Step::rwv_printed_quoted(
                &ww("w"),
                "rwv -C ",
                "member remove local/remotes/app --delete",
            )
            .expect(Exit::refuses_kind(RefusalKind::DroppedRepoHasUniqueCommits))
            .claim(Claim::OutputContains("branch side in submodule sub"))
            .claim(Claim::DirStands(Machine::A, "weave/local/remotes/app")),
            Step::git(
                &a(),
                Repo::App,
                &["-C", "sub", "branch", "-q", "-D", "side"],
            ),
            Step::rwv(&a(), &["member", "remove", APP, "--delete"])
                .expect(Exit::Succeeds)
                .claim(Claim::DirGone(Machine::A, "weave/local/remotes/app")),
        ],
    )
}

/// A submodule whose remote rewrote a branch the store holds nothing else
/// of: the removal's refresh keeps no tip of it in the submodule store, which
/// no verb could drop, so the removal goes through.
pub fn store_removal_keeps_nothing_of_a_submodule_remote_rewrite() -> Scenario {
    let file = "protocol.file.allow=always";
    let mut steps = vec![
        Step::git(
            &a(),
            Repo::App,
            &["-c", file, "submodule", "add", "-q", "../lib.git", "sub"],
        ),
        Step::git(&a(), Repo::App, &["commit", "-qm", "add sub"]),
        Step::git(&a(), Repo::App, &["push", "-q", "origin", "main"])
            .pushes(Remote::origin(Repo::App), "main"),
        Step::git(
            &a(),
            Repo::App,
            &[
                "-C",
                "sub",
                "commit",
                "-q",
                "--allow-empty",
                "-m",
                "rewritten-away",
            ],
        ),
        Step::git(
            &a(),
            Repo::App,
            &["-C", "sub", "push", "-q", "origin", "HEAD:refs/heads/topic"],
        )
        .pushes(Remote::origin(Repo::Lib), "topic"),
        Step::git(
            &a(),
            Repo::App,
            &["-C", "sub", "reset", "-q", "--hard", "HEAD~1"],
        ),
        Step::git(&Place::Forge, Repo::Lib, &["fetch", "-q", "origin"]),
    ];
    steps.extend(
        Step::forge_force_push(Repo::Lib, "topic", "replaced")
            .into_iter()
            .map(|step| step.may_strand(&[Repo::Lib])),
    );
    steps.push(
        Step::rwv(&a(), &["member", "remove", APP, "--delete"])
            .expect(Exit::Succeeds)
            .claim(Claim::DirGone(Machine::A, "weave/local/remotes/app")),
    );
    scenario(
        "a store removal keeps nothing of a submodule remote's rewrite",
        steps,
    )
}

/// The clone's own refresh keeps the tip a remote rewrote a branch off as a
/// backup, and the removal refuses naming it; the drop it prints, run as
/// printed, lets the removal through on the next run, with no new backup.
pub fn store_removal_after_a_rewrite_ends_once_its_backup_is_dropped() -> Scenario {
    let mut steps = vec![
        Step::git(&a(), Repo::App, &["switch", "-q", "-c", "topic"]),
        Step::commit(&a(), Repo::App, "rewritten-away"),
        Step::git(&a(), Repo::App, &["push", "-q", "origin", "topic"])
            .pushes(Remote::origin(Repo::App), "topic"),
        Step::git(&a(), Repo::App, &["switch", "-q", "main"]),
        Step::git(&a(), Repo::App, &["branch", "-q", "-D", "topic"]),
        Step::git(&Place::Forge, Repo::App, &["fetch", "-q", "origin"]),
    ];
    steps.extend(Step::forge_force_push(Repo::App, "topic", "replaced"));
    steps.extend([
        Step::rwv(&a(), &["member", "remove", APP, "--delete"])
            .expect(Exit::refuses_kind(RefusalKind::DroppedRepoHasUniqueCommits))
            .claim(Claim::OutputContains("rwv backup drop local/remotes/app "))
            .claim(Claim::DirStands(Machine::A, "weave/local/remotes/app")),
        Step::rwv_printed_quoted(&a(), "rwv backup drop ", "")
            .expect(Exit::Succeeds)
            .may_strand(&[Repo::App]),
        Step::rwv(&a(), &["member", "remove", APP, "--delete"])
            .expect(Exit::Succeeds)
            .claim(Claim::DirGone(Machine::A, "weave/local/remotes/app")),
    ]);
    scenario(
        "a store removal after a rewrite ends once its backup is dropped",
        steps,
    )
}

/// A landing's prune judges the target's clone against its remotes as they
/// are: a branch whose remote copy was deleted after it was pushed holds its
/// commits alone, and the clone stays.
pub fn landing_prune_judges_against_the_remote_as_it_is() -> Scenario {
    scenario(
        "a landing's prune asks the remote as it is",
        vec![
            create("w"),
            Step::git(&a(), Repo::App, &["switch", "-q", "-c", "topic"]),
            Step::commit(&a(), Repo::App, "pushed-then-deleted"),
            Step::git(&a(), Repo::App, &["push", "-q", "origin", "topic"])
                .pushes(Remote::origin(Repo::App), "topic"),
            Step::git(&a(), Repo::App, &["switch", "-q", "main"]),
            Step::forge_delete_branch(Repo::App, "topic"),
            Step::rwv(&ww("w"), &["member", "remove", APP, "--delete"]).expect(Exit::Succeeds),
            Step::rwv(&ww("w"), &["land", "--allow-member-change", APP])
                .expect(Exit::Succeeds)
                .claim(Claim::OutputContains(
                    "local/remotes/app: prune in the target's workspace skipped",
                ))
                .claim(Claim::OutputContains("branch topic"))
                .claim(Claim::DirStands(Machine::A, "weave/local/remotes/app")),
        ],
    )
}

