/// `stack-not-containing`: `w2`, in a workweave of its own, was cut from an
/// older commit of `w1`; `w1`'s `sync` prints `w2` as lacking `w1`'s tip,
/// with C35, C12 and C36; C36, run in `w2`'s workspace, takes `w1` in, and
/// the rerun shows the state that remains, checked out elsewhere.
pub fn stack_not_containing() -> Scenario {
    let mut steps = vec![
        Step::rwv(&a(), &["branch", "set-history", "linear"]).expect(Exit::Succeeds),
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app-1"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(
            &ww("w1"),
            &["workweave", "create", "w2", "--new-branch", "w2"],
        )
        .expect(Exit::Succeeds),
        Step::commit(&ww("w2"), Repo::App, "w2-app"),
        Step::rwv(&ww("w2"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::commit(&ww("w1"), Repo::App, "w1-app-2"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
    ];
    steps.extend(main_moves_app("main-app"));
    steps.extend([
        Step::rwv(&ww("w1"), &["sync"])
            .expect(Exit::refuses(Repo::Proj, State::TargetDependentLacksTip))
            .claim(Claim::JudgedOnly(
                Repo::Proj,
                State::TargetDependentLacksTip,
            ))
            .claim(Claim::OutputContains("rwv land"))
            .claim(Claim::OutputContains(
                "rwv branch set-mode w2 feature --target main",
            ))
            .claim(Claim::OutputContains("rwv sync"))
            .claim(Claim::LocalStateUnchanged(ww("w1")))
            .claim(Claim::LocalStateUnchanged(ww("w2"))),
        Step::rwv_printed_exactly(&ww("w2"), "rwv sync").expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["sync"])
            .expect(Exit::refuses(Repo::Proj, State::TargetDependentCheckedOut))
            .claim(Claim::JudgedOnly(
                Repo::Proj,
                State::TargetDependentCheckedOut,
            )),
    ]);
    scenario("stack: a dependent cut from an older commit", steps)
}

/// `stack-carried` where `w2`'s replay conflicts with `main`'s new work: the
/// sync stops in `w1`'s checkout of `app` with `w2` not moved; the operator
/// resolves it and continues, and `w2` is carried, or aborts, and `w1` and
/// `w2` are as they were.
pub fn stack_carry_conflict(then: AfterHandContinue) -> Scenario {
    let mut steps = vec![
        Step::rwv(&a(), &["branch", "set-history", "linear"]).expect(Exit::Succeeds),
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        dependent_of(&ww("w1"), "w2", "proj--w1"),
        Step::hand_edit(&ww("w1"), Repo::App, "README", "app", "beta"),
        Step::git(&ww("w1"), Repo::App, &["commit", "-qam", "w2-app"]),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["switch", "proj--w1"]).expect(Exit::Succeeds),
        Step::hand_edit(&a(), Repo::App, "README", "app", "alpha"),
        Step::git(&a(), Repo::App, &["commit", "-qam", "main-app"]),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["sync"])
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .claim(Claim::OutputContains(
                "carrying 'w2' along in local/remotes/app",
            ))
            .claim(Claim::OutputContains("rwv sync --continue"))
            .claim(Claim::OutputContains("rwv abort")),
        Step::git(&ww("w1"), Repo::App, &["log", "--format=%s", "-1", "w2"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLine("w2-app")),
    ];
    match then {
        AfterHandContinue::Continue => steps.extend([
            Step::git(&ww("w1"), Repo::App, &["checkout", "--theirs", "README"]),
            Step::git(&ww("w1"), Repo::App, &["add", "README"]),
            Step::rwv(&ww("w1"), &["sync", "--continue"])
                .expect(Exit::Succeeds)
                .resolved_by_hand(&[Repo::App])
                .may_rewind(&[Repo::App])
                .claim(Claim::OutputContains("carried 'w2' along"))
                .claim(Claim::OnBranch {
                    at: ww("w1"),
                    repo: Repo::App,
                    branch: "proj--w1",
                })
                .claim(Claim::PinsReplayed {
                    at: ww("w1"),
                    rev: "w2",
                    member: Repo::App,
                    subject: "w2-app",
                    reached_from: "w2",
                }),
            Step::git(
                &ww("w1"),
                Repo::App,
                &["merge-base", "--is-ancestor", "proj--w1", "w2"],
            )
            .expect(Exit::Succeeds),
        ]),
        AfterHandContinue::Abort => steps.extend([
            Step::rwv(&ww("w1"), &["abort"])
                .expect(Exit::Succeeds)
                .may_rewind(&[Repo::App])
                .claim(Claim::OutputLacks("foreign"))
                .claim(Claim::OnBranch {
                    at: ww("w1"),
                    repo: Repo::App,
                    branch: "proj--w1",
                }),
            Step::git(
                &ww("w1"),
                Repo::App,
                &["log", "--format=%s", "-1", "proj--w1"],
            )
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLine("w1-app")),
            Step::git(&ww("w1"), Repo::App, &["diff", "--quiet", "HEAD"]).expect(Exit::Succeeds),
            Step::git(&ww("w1"), Repo::App, &["log", "--format=%s", "-1", "w2"])
                .expect(Exit::Succeeds)
                .claim(Claim::OutputLine("w2-app")),
        ]),
    }
    scenario(
        "stack: a carry that conflicts stops before any dependent moves",
        steps,
    )
}

/// `stack-carry-conflict` with the conflict in the project repo: `w2` and
/// `main` both edit a project file. The sync stops carrying `w2` in
/// the project checkout, which the replay leaves detached; once the operator
/// resolves it, the printed `rwv sync --continue` carries `w2` and puts the
/// checkout back on `w1`'s branch.
pub fn a_carry_stopped_in_the_project_continues() -> Scenario {
    let mut steps = vec![
        Step::rwv(&a(), &["branch", "set-history", "linear"]).expect(Exit::Succeeds),
        Step::commit(&a(), Repo::Proj, "notes"),
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        dependent_of(&ww("w1"), "w2", "proj--w1"),
        Step::hand_edit(
            &ww("w1"),
            Repo::Proj,
            "notes.txt",
            "notes\n",
            "notes on w2\n",
        ),
        Step::git(&ww("w1"), Repo::Proj, &["commit", "-qam", "w2-proj"]),
        Step::rwv(&ww("w1"), &["switch", "proj--w1"]).expect(Exit::Succeeds),
        Step::hand_edit(&a(), Repo::Proj, "notes.txt", "notes\n", "notes on main\n"),
        Step::git(&a(), Repo::Proj, &["commit", "-qam", "main-proj"]),
    ];
    steps.extend(main_moves_app("main-app"));
    steps.extend([
        Step::rwv(&ww("w1"), &["sync"])
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .claim(Claim::OutputContains("carrying 'w2' along"))
            .claim(Claim::OutputContains("rwv sync --continue")),
        Step::git(
            &ww("w1"),
            Repo::Proj,
            &["checkout", "--theirs", "notes.txt"],
        ),
        Step::git(&ww("w1"), Repo::Proj, &["add", "notes.txt"]),
        Step::rwv(&ww("w1"), &["sync", "--continue"])
            .expect(Exit::Succeeds)
            .resolved_by_hand(&[Repo::Proj])
            .claim(Claim::OutputContains("carried 'w2' along"))
            .claim(Claim::OnBranch {
                at: ww("w1"),
                repo: Repo::Proj,
                branch: "proj--w1",
            }),
        Step::git(
            &ww("w1"),
            Repo::Proj,
            &["merge-base", "--is-ancestor", "proj--w1", "w2"],
        )
        .expect(Exit::Succeeds),
        Step::git(
            &ww("w1"),
            Repo::App,
            &["merge-base", "--is-ancestor", "proj--w1", "w2"],
        )
        .expect(Exit::Succeeds),
    ]);
    scenario(
        "stack: a carry stopped in the project repo continues",
        steps,
    )
}

/// [`a_carry_stopped_in_the_project_continues`] with the conflict in
/// `rwv.toml`: `w2` and `main` each add a `[workweave]` table, under a
/// comment of their own, at the same place. The carry's stop lists the table,
/// and the printed `--keep yours` keeps `w2`'s, comment and all: yours is the
/// dependent's side of the replay.
pub fn a_carry_stopped_on_rwv_toml_keeps_the_dependents_side() -> Scenario {
    let table = |at: &Place, mark: &str, file: &str| {
        Step::hand_edit(
            at,
            Repo::Proj,
            "rwv.toml",
            "[integrations.vscode-workspace]\nenabled = false\n",
            &format!(
                "[integrations.vscode-workspace]\nenabled = false\n\n# {mark}\n[workweave]\n\
                 copy = [\"{file}\"]\n"
            ),
        )
    };
    let mut steps = vec![
        Step::rwv(&a(), &["branch", "set-history", "linear"]).expect(Exit::Succeeds),
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        dependent_of(&ww("w1"), "w2", "proj--w1"),
        table(&ww("w1"), "W2-SIDE", "w2.txt"),
        Step::git(&ww("w1"), Repo::Proj, &["commit", "-qam", "w2-proj"]),
        Step::rwv(&ww("w1"), &["switch", "proj--w1"]).expect(Exit::Succeeds),
        table(&a(), "MAIN-SIDE", "main.txt"),
        Step::git(&a(), Repo::Proj, &["commit", "-qam", "main-proj"]),
    ];
    steps.extend(main_moves_app("main-app"));
    steps.extend([
        Step::rwv(&ww("w1"), &["sync"])
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .claim(Claim::OutputContains("carrying 'w2' along"))
            .claim(Claim::OutputContains(
                "rwv.toml entry [workweave] is in conflict",
            ))
            .claim(Claim::OutputContains("rwv sync --continue --keep yours")),
        Step::rwv_printed_holding(&ww("w1"), "rwv sync --continue", "--keep yours")
            .expect(Exit::Succeeds)
            .may_strand(&[Repo::Proj])
            .claim(Claim::OutputContains("carried 'w2' along"))
            .claim(Claim::OnBranch {
                at: ww("w1"),
                repo: Repo::Proj,
                branch: "proj--w1",
            }),
        Step::git(&ww("w1"), Repo::Proj, &["show", "w2:rwv.toml"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputContains(
                "# W2-SIDE\n[workweave]\ncopy = [\"w2.txt\"]",
            ))
            .claim(Claim::OutputLacks("MAIN-SIDE"))
            .claim(Claim::OutputLacks("main.txt")),
    ]);
    scenario(
        "stack: a carry stopped on rwv.toml keeps the dependent's side",
        steps,
    )
}

/// [`a_carry_stopped_on_rwv_toml_keeps_the_dependents_side`] taking the
/// incoming side: the stop's legend names the carried branch as yours, the
/// continue keeps no backup of the `rwv.toml` it writes over, and the replay that drops
/// `w2`'s one commit leaves its old tip in the rebased backup the line names.
pub fn a_carry_that_drops_a_commit_keeps_its_rebased_backup() -> Scenario {
    let table = |at: &Place, mark: &str, file: &str| {
        Step::hand_edit(
            at,
            Repo::Proj,
            "rwv.toml",
            "[integrations.vscode-workspace]\nenabled = false\n",
            &format!(
                "[integrations.vscode-workspace]\nenabled = false\n\n# {mark}\n[workweave]\n\
                 copy = [\"{file}\"]\n"
            ),
        )
    };
    let mut steps = vec![
        Step::rwv(&a(), &["branch", "set-history", "linear"]).expect(Exit::Succeeds),
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        dependent_of(&ww("w1"), "w2", "proj--w1"),
        table(&ww("w1"), "W2-SIDE", "w2.txt"),
        Step::git(&ww("w1"), Repo::Proj, &["commit", "-qam", "w2-proj"]),
        Step::rwv(&ww("w1"), &["switch", "proj--w1"]).expect(Exit::Succeeds),
        table(&a(), "MAIN-SIDE", "main.txt"),
        Step::git(&a(), Repo::Proj, &["commit", "-qam", "main-proj"]),
    ];
    steps.extend(main_moves_app("main-app"));
    steps.extend([
        Step::rwv(&ww("w1"), &["sync"])
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .claim(Claim::OutputContains(
                "(yours: 'w2', the branch being carried; incoming: the side it takes in)",
            )),
        Step::rwv_printed_holding(&ww("w1"), "rwv sync --continue", "--keep incoming")
            .expect(Exit::Succeeds)
            .may_strand(&[Repo::Proj])
            .claim(Claim::OutputLacks("backup HEAD/"))
            .claim(Claim::OutputLacks("kept in backup"))
            .claim(Claim::OutputContains(
                "the tip it left kept in the rebased backup w2/rebased-",
            )),
        Step::git(
            &ww("w1"),
            Repo::Proj,
            &["for-each-ref", "refs/rwv/backup/w2/"],
        )
        .claim(Claim::OutputContains("refs/rwv/backup/w2/rebased-")),
        Step::git(&ww("w1"), Repo::Proj, &["log", "--format=%s", "w2"])
            .claim(Claim::OutputLacks("w2-proj")),
    ]);
    scenario(
        "stack: a carry that drops a commit keeps its rebased backup",
        steps,
    )
}

/// A landing of `w1` whose carry of `w2` stops in the project repo, `w2`'s
/// project commit also changing `app`'s entry: `rwv land --continue` judges
/// the landing's own entries, not the `rwv.toml` the stopped carry left in
/// the checkout, says so to a consent named for them, and completes with `w2`
/// carried.
pub fn a_landing_whose_carry_stopped_in_the_project_continues() -> Scenario {
    let declared = declared_branch_text(Repo::App, "main");
    let edited = format!("{declared}\nrecurse-submodules = false");
    let mut steps = vec![
        Step::rwv(&a(), &["branch", "set-history", "linear"]).expect(Exit::Succeeds),
        Step::commit(&a(), Repo::Proj, "notes"),
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        dependent_of(&ww("w1"), "w2", "proj--w1"),
        Step::hand_edit(
            &ww("w1"),
            Repo::Proj,
            "notes.txt",
            "notes\n",
            "notes on w2\n",
        ),
        Step::hand_edit(&ww("w1"), Repo::Proj, "rwv.toml", &declared, &edited),
        Step::git(&ww("w1"), Repo::Proj, &["commit", "-qam", "w2-proj"]),
        Step::rwv(&ww("w1"), &["switch", "proj--w1"]).expect(Exit::Succeeds),
        Step::hand_edit(&a(), Repo::Proj, "notes.txt", "notes\n", "notes on main\n"),
        Step::git(&a(), Repo::Proj, &["commit", "-qam", "main-proj"]),
    ];
    steps.extend(main_moves_app("main-app"));
    steps.extend([
        Step::rwv(&ww("w1"), &["land"])
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .claim(Claim::OutputContains("carrying 'w2' along"))
            .claim(Claim::OutputContains("rwv land --continue")),
        Step::git(
            &ww("w1"),
            Repo::Proj,
            &["checkout", "--theirs", "notes.txt"],
        ),
        Step::git(&ww("w1"), Repo::Proj, &["add", "notes.txt"]),
        Step::rwv(
            &ww("w1"),
            &[
                "land",
                "--continue",
                "--allow-member-change",
                "local/remotes/app",
            ],
        )
        .expect(Exit::refuses_kind(RefusalKind::InapplicableFlag))
        .claim(Claim::OutputContains(
            "judged again once the carry is continued",
        )),
        Step::rwv(&ww("w1"), &["land", "--continue"])
            .expect(Exit::Succeeds)
            .resolved_by_hand(&[Repo::Proj])
            .claim(Claim::OutputContains("carried 'w2' along"))
            .claim(Claim::OutputLacks("member change")),
        Step::git(
            &ww("w1"),
            Repo::Proj,
            &["merge-base", "--is-ancestor", "proj--w1", "w2"],
        )
        .expect(Exit::Succeeds),
        Step::git(
            &a(),
            Repo::Proj,
            &["grep", "-q", "recurse-submodules", "main", "--", "rwv.toml"],
        )
        .expect(Exit::Code(1)),
    ]);
    scenario(
        "stack: a landing whose carry stopped in the project repo continues",
        steps,
    )
}

/// `w3` onto `w2` onto `w1`, `w1` holding an `app` commit its lock does not
/// pin, so its sync writes a relock commit; `w3`'s replay conflicts after
/// `w2`'s project branch composed on that commit. `rwv sync --continue`
/// keeps the relock commit and every carried project branch holds `w1`'s
/// project tip.
pub fn a_sync_continued_after_its_relock_keeps_it() -> Scenario {
    let mut steps = vec![
        Step::rwv(&a(), &["branch", "set-history", "linear"]).expect(Exit::Succeeds),
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::commit(&ww("w1"), Repo::App, "w1-unpinned"),
        dependent_of(&ww("w1"), "w2", "proj--w1"),
        Step::git(
            &ww("w1"),
            Repo::App,
            &["merge", "--ff-only", "-q", "proj--w1"],
        ),
        Step::commit(&ww("w1"), Repo::App, "w2-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        dependent_of(&ww("w1"), "w3", "w2"),
        Step::hand_edit(&ww("w1"), Repo::App, "README", "app", "beta"),
        Step::git(&ww("w1"), Repo::App, &["commit", "-qam", "w3-app"]),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["switch", "proj--w1"]).expect(Exit::Succeeds),
        Step::hand_edit(&a(), Repo::App, "README", "app", "alpha"),
        Step::git(&a(), Repo::App, &["commit", "-qam", "main-app"]),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["sync"])
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .claim(Claim::OutputContains("carrying 'w3' along")),
        Step::git(&ww("w1"), Repo::App, &["checkout", "--theirs", "README"]),
        Step::git(&ww("w1"), Repo::App, &["add", "README"]),
        Step::rwv(&ww("w1"), &["sync", "--continue"])
            .expect(Exit::Succeeds)
            .resolved_by_hand(&[Repo::App])
            .may_rewind(&[Repo::App])
            .claim(Claim::OutputContains("carried 'w3' along")),
        Step::git(
            &ww("w1"),
            Repo::Proj,
            &["log", "-1", "--format=%s", "proj--w1"],
        )
        .expect(Exit::Succeeds)
        .claim(Claim::OutputContains("relock after sync")),
    ];
    for (repo, parent, dependent) in [
        (Repo::Proj, "proj--w1", "w2"),
        (Repo::Proj, "w2", "w3"),
        (Repo::App, "proj--w1", "w2"),
        (Repo::App, "w2", "w3"),
    ] {
        steps.push(
            Step::git(
                &ww("w1"),
                repo,
                &["merge-base", "--is-ancestor", parent, dependent],
            )
            .expect(Exit::Succeeds),
        );
    }
    scenario("stack: a sync continued after its relock keeps it", steps)
}

/// `a-sync-continued-after-its-relock-keeps-it`, with a commit made in
/// `w1`'s project repo during the stop: the project branch `w2` was composed
/// on before the stop no longer sits on `w1`'s project tip, so the continued
/// carry composes it again and `w2` holds `w1`'s project tip.
pub fn a_sync_continued_after_its_project_tip_moved_recomposes_the_project_carry() -> Scenario {
    let steps = vec![
        Step::rwv(&a(), &["branch", "set-history", "linear"]).expect(Exit::Succeeds),
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::commit(&ww("w1"), Repo::App, "w1-unpinned"),
        dependent_of(&ww("w1"), "w2", "proj--w1"),
        Step::git(
            &ww("w1"),
            Repo::App,
            &["merge", "--ff-only", "-q", "proj--w1"],
        ),
        Step::commit(&ww("w1"), Repo::App, "w2-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        dependent_of(&ww("w1"), "w3", "w2"),
        Step::hand_edit(&ww("w1"), Repo::App, "README", "app", "beta"),
        Step::git(&ww("w1"), Repo::App, &["commit", "-qam", "w3-app"]),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["switch", "proj--w1"]).expect(Exit::Succeeds),
        Step::hand_edit(&a(), Repo::App, "README", "app", "alpha"),
        Step::git(&a(), Repo::App, &["commit", "-qam", "main-app"]),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["sync"])
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .claim(Claim::OutputContains("carrying 'w3' along")),
        Step::commit(&ww("w1"), Repo::Proj, "w1-later"),
        Step::git(&ww("w1"), Repo::App, &["checkout", "--theirs", "README"]),
        Step::git(&ww("w1"), Repo::App, &["add", "README"]),
        Step::rwv(&ww("w1"), &["sync", "--continue"])
            .expect(Exit::Succeeds)
            .resolved_by_hand(&[Repo::App])
            .may_rewind(&[Repo::App]),
        Step::git(
            &ww("w1"),
            Repo::Proj,
            &["merge-base", "--is-ancestor", "proj--w1", "w2"],
        )
        .expect(Exit::Succeeds),
    ];
    scenario(
        "stack: a sync continued after its project tip moved recomposes the project carry",
        steps,
    )
}

/// `verb` under `history`, killed at `point`, right after its relock
/// commit and before it journaled that commit's tip: `rwv abort` puts
/// everything back, the relock commit kept in the project branch's slot like
/// any tip it resets.
pub fn a_verb_killed_after_its_relock_commit_is_aborted(
    verb: &'static str,
    history: &'static str,
    point: &'static str,
) -> Scenario {
    let steps = vec![
        Step::rwv(&a(), &["branch", "set-history", history]).expect(Exit::Succeeds),
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::commit(&ww("w1"), Repo::Proj, "w1-proj"),
        Step::commit(&a(), Repo::App, "main-app"),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv_paused(&ww("w1"), &[verb], point, "relocking"),
        Step::kill("relocking"),
        Step::rwv(&ww("w1"), &["abort"])
            .expect(Exit::Succeeds)
            .may_strand(&[Repo::App, Repo::Proj])
            .may_rewind(&[Repo::App, Repo::Proj])
            .may_restore(&[Repo::App, Repo::Proj])
            .claim(Claim::OutputContains(
                "projects/proj: what abort discarded is kept as backup proj--w1/aborted",
            )),
        Step::rwv(&ww("w1"), &["status"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLacks("in progress")),
        Step::git(&ww("w1"), Repo::Proj, &["log", "-1", "--format=%s"])
            .claim(Claim::OutputLine("w1-proj")),
    ];
    scenario("a verb killed after its relock commit, aborted", steps)
}

/// A sync run with `--history` for one run, killed as its op starts, before
/// anything moved: `--continue` resumes it under the history it was run with.
pub fn a_sync_killed_as_its_op_starts_continues_under_its_history() -> Scenario {
    let steps = vec![
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::commit(&a(), Repo::App, "main-app"),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["sync"]).expect(Exit::refuses(Repo::App, State::HistoryUnset)),
        Step::rwv_paused(
            &ww("w1"),
            &["sync", "--history", "linear"],
            "op-savepoint-taken",
            "syncing",
        ),
        Step::kill("syncing"),
        Step::rwv(&ww("w1"), &["sync", "--continue"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["status"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLacks("in progress")),
        Step::git(&ww("w1"), Repo::App, &["log", "--format=%s", "-2"])
            .claim(Claim::OutputLine("w1-app"))
            .claim(Claim::OutputLine("main-app")),
    ];
    scenario("a sync killed as its op starts, continued", steps)
}

/// A sync or a landing whose relock commit was made and killed before its
/// tip was journaled, then continued into a stop on the carry of `w2` in
/// `app`: the printed `rwv abort` puts back what the verb moved, the relock
/// commit included.
pub fn a_verb_killed_after_its_relock_commit_then_stopped(
    verb: &'static str,
    point: &'static str,
) -> Scenario {
    let steps = vec![
        Step::rwv(&a(), &["branch", "set-history", "linear"]).expect(Exit::Succeeds),
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::commit(&ww("w1"), Repo::App, "w1-unpinned"),
        dependent_of(&ww("w1"), "w2", "proj--w1"),
        Step::git(
            &ww("w1"),
            Repo::App,
            &["merge", "--ff-only", "-q", "proj--w1"],
        ),
        Step::hand_edit(&ww("w1"), Repo::App, "README", "app", "beta"),
        Step::git(&ww("w1"), Repo::App, &["commit", "-qam", "w2-app"]),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["switch", "proj--w1"]).expect(Exit::Succeeds),
        Step::hand_edit(&a(), Repo::App, "README", "app", "alpha"),
        Step::git(&a(), Repo::App, &["commit", "-qam", "main-app"]),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv_paused(&ww("w1"), &[verb], point, "relocking"),
        Step::kill("relocking"),
        Step::rwv(&ww("w1"), &[verb, "--continue"])
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .claim(Claim::OutputContains(
                "carrying 'w2' along in local/remotes/app",
            )),
        Step::rwv(&ww("w1"), &["abort"])
            .expect(Exit::Succeeds)
            .may_rewind(&[Repo::App])
            .may_restore(&[Repo::App, Repo::Proj])
            .claim(Claim::OutputLacks("foreign")),
        Step::git(&ww("w1"), Repo::Proj, &["log", "--format=%s", "proj--w1"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLacks("relock after")),
    ];
    scenario(
        "stack: a verb killed after its relock commit, then stopped",
        steps,
    )
}

/// `stack-carried`, killed after the carry of `w2` in `app` journaled what
/// it composed and before the checkout went back on its branch: the
/// checkout is on no branch, and the printed `rwv sync --continue` puts it
/// back and carries on.
pub fn a_sync_killed_after_journaling_a_composed_carry_continues() -> Scenario {
    let mut steps = stack_on_a_seat();
    steps.extend(main_moves_app("main-app"));
    steps.extend([
        Step::rwv_paused(&ww("w1"), &["sync"], "carry-journaled", "carrying"),
        Step::kill("carrying"),
        Step::rwv(&ww("w1"), &["sync", "--continue"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputContains("carried 'w2' along")),
        Step::git(&ww("w1"), Repo::App, &["symbolic-ref", "-q", "HEAD"]).expect(Exit::Succeeds),
        Step::git(&ww("w1"), Repo::Proj, &["symbolic-ref", "-q", "HEAD"]).expect(Exit::Succeeds),
    ]);
    scenario(
        "stack: a sync killed after journaling a composed carry continues",
        steps,
    )
}

/// What wrote `w1`'s project tip before its carry of `w2` stopped.
#[derive(Debug, Clone, Copy)]
pub enum BeforeTheCarry {
    /// A sync's relock commit, pinning an `app` commit the lock did not.
    SyncRelocked,
    /// A landing's project merge, under a `merge` project with a `linear`
    /// `app`, by a git without `merge-tree --write-tree`.
    #[cfg(unix)]
    LandingMerged,
    /// Nothing more: the carry's replay was then finished by hand.
    FinishedByHand,
}

/// `w1`'s sync or landing stops carrying `w2`, whose `app` commit conflicts
/// with `main`'s, after rwv wrote `w1`'s project tip or once the operator
/// finished the carry's replay by hand; `rwv abort` reads every tip as the
/// operation's own and puts `w1` and `w2` back as they were.
pub fn abort_after_a_carry_stop(before: BeforeTheCarry) -> Scenario {
    let landing = !matches!(
        before,
        BeforeTheCarry::SyncRelocked | BeforeTheCarry::FinishedByHand
    );
    let history = if landing { "merge" } else { "linear" };
    let unpinned = matches!(before, BeforeTheCarry::SyncRelocked);
    let mut steps =
        vec![Step::rwv(&a(), &["branch", "set-history", history]).expect(Exit::Succeeds)];
    if history == "merge" {
        steps.push(
            Step::rwv(
                &a(),
                &[
                    "branch",
                    "set-history",
                    "linear",
                    "--repo",
                    "local/remotes/app",
                ],
            )
            .expect(Exit::Succeeds),
        );
    }
    steps.extend([
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
    ]);
    if unpinned {
        steps.push(Step::commit(&ww("w1"), Repo::App, "w1-unpinned"));
    }
    steps.push(dependent_of(&ww("w1"), "w2", "proj--w1"));
    if unpinned {
        steps.push(Step::git(
            &ww("w1"),
            Repo::App,
            &["merge", "--ff-only", "-q", "proj--w1"],
        ));
    }
    let verb = if landing { "land" } else { "sync" };
    steps.extend([
        Step::hand_edit(&ww("w1"), Repo::App, "README", "app", "beta"),
        Step::git(&ww("w1"), Repo::App, &["commit", "-qam", "w2-app"]),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["switch", "proj--w1"]).expect(Exit::Succeeds),
        Step::hand_edit(&a(), Repo::App, "README", "app", "alpha"),
        Step::git(&a(), Repo::App, &["commit", "-qam", "main-app"]),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &[verb])
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .claim(Claim::OutputContains(
                "carrying 'w2' along in local/remotes/app",
            )),
    ]);
    if matches!(before, BeforeTheCarry::FinishedByHand) {
        steps.extend([
            Step::git(&ww("w1"), Repo::App, &["checkout", "--theirs", "README"]),
            Step::git(&ww("w1"), Repo::App, &["add", "README"]),
            Step::git(
                &ww("w1"),
                Repo::App,
                &["-c", "core.editor=true", "rebase", "--continue"],
            ),
        ]);
    }
    let w1_app = if unpinned { "w1-unpinned" } else { "w1-app" };
    let abort = match before {
        BeforeTheCarry::FinishedByHand => Step::rwv(&ww("w1"), &["abort"]).claim(
            Claim::OutputContains("local/remotes/app: what abort discarded is kept as backup"),
        ),
        _ => Step::rwv(&ww("w1"), &["abort"]),
    };
    steps.extend([
        abort
            .expect(Exit::Succeeds)
            .may_rewind(&[Repo::App])
            .may_restore(&[Repo::App, Repo::Proj])
            .claim(Claim::OutputLacks("foreign"))
            .claim(Claim::OnBranch {
                at: ww("w1"),
                repo: Repo::App,
                branch: "proj--w1",
            })
            .claim(Claim::OnBranch {
                at: ww("w1"),
                repo: Repo::Proj,
                branch: "proj--w1",
            }),
        Step::git(
            &ww("w1"),
            Repo::App,
            &["log", "--format=%s", "-1", "proj--w1"],
        )
        .expect(Exit::Succeeds)
        .claim(Claim::OutputLine(w1_app)),
        Step::git(&ww("w1"), Repo::App, &["log", "--format=%s", "-1", "w2"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLine("w2-app")),
        Step::git(&ww("w1"), Repo::App, &["log", "--format=%s", "proj--w1"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLacks("main-app")),
        Step::git(&ww("w1"), Repo::Proj, &["log", "--format=%s", "proj--w1"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLacks("relock after"))
            .claim(Claim::OutputLacks("Merge")),
    ]);
    Scenario {
        name: "stack: an abort after a carry stopped",
        seed: match before {
            #[cfg(unix)]
            BeforeTheCarry::LandingMerged => Seed::default().old_git(),
            BeforeTheCarry::SyncRelocked | BeforeTheCarry::FinishedByHand => Seed::default(),
        },
        steps,
    }
}

/// A `merge` project with `linear` `app` and `lib`: `w1` commits in both,
/// `w2` onto `w1` only in `app`, and `main` moves both. `w1`'s sync merges
/// its project branch and rebases both members; `w2`'s project branch,
/// carried, holds `w1`'s new project tip and pins the rebased `lib` it
/// inherits, not the commit the rebase replaced.
pub fn a_dependent_carried_onto_a_merged_project_pins_what_it_inherits() -> Scenario {
    let linear = |repo: &'static str| {
        Step::rwv(&a(), &["branch", "set-history", "linear", "--repo", repo]).expect(Exit::Succeeds)
    };
    let mut steps = vec![
        Step::rwv(&a(), &["branch", "set-history", "merge"]).expect(Exit::Succeeds),
        linear("local/remotes/app"),
        linear("local/remotes/lib"),
        create("w1"),
        Step::commit(&ww("w1"), Repo::App, "w1-app"),
        Step::commit(&ww("w1"), Repo::Lib, "w1-lib"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        dependent_of(&ww("w1"), "w2", "proj--w1"),
        Step::commit(&ww("w1"), Repo::App, "w2-app"),
        Step::rwv(&ww("w1"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["switch", "proj--w1"]).expect(Exit::Succeeds),
        Step::commit(&a(), Repo::App, "main-app"),
        Step::commit(&a(), Repo::Lib, "main-lib"),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w1"), &["sync"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputContains("carried 'w2' along"))
            .claim(Claim::PinsReplayed {
                at: ww("w1"),
                rev: "w2",
                member: Repo::Lib,
                subject: "w1-lib",
                reached_from: "w2",
            })
            .claim(Claim::PinsReplayed {
                at: ww("w1"),
                rev: "w2",
                member: Repo::App,
                subject: "w2-app",
                reached_from: "w2",
            }),
        Step::git(
            &ww("w1"),
            Repo::Proj,
            &["merge-base", "--is-ancestor", "proj--w1", "w2"],
        )
        .expect(Exit::Succeeds),
    ];
    steps.push(Step::rwv(&ww("w1"), &["status"]).expect(Exit::Succeeds));
    scenario(
        "stack: a dependent carried onto a merged project pins what it inherits",
        steps,
    )
}

/// How a carried stack someone built on is ended.
#[derive(Debug, Clone, Copy)]
pub enum BuiltOnChoice {
    /// `rwv abort`: everything put back, the commit built on `w2` kept as a
    /// backup.
    Abort,
    /// `rwv land --continue`: the landing finished, `w2` keeping the commit.
    Continue,
}

/// `stack-carried-by-a-landing` killed after its carry moved `w2`, then a
/// commit on `w2`: `rwv abort` puts `w2` back, keeping that commit as a
/// backup the printed show line returns, or `rwv land --continue` finishes
/// with `w2` keeping it.
pub fn abort_a_carried_stack_built_on(choice: BuiltOnChoice) -> Scenario {
    let mut steps = stack_on_a_seat();
    steps.extend(main_moves_app("main-app"));
    steps.extend([
        Step::rwv_paused(&ww("w1"), &["land"], "composed", "landing"),
        Step::kill("landing"),
        Step::hand_commit(&ww("w1"), Repo::App, "w2", &[("more.txt", "more\n")]),
    ]);
    match choice {
        BuiltOnChoice::Abort => steps.extend([
            Step::rwv(&ww("w1"), &["abort"])
                .expect(Exit::Succeeds)
                .may_rewind(&[Repo::App])
                .may_restore(&[Repo::App, Repo::Proj])
                .claim(Claim::OutputContains("kept as backup"))
                .claim(Claim::OnBranch {
                    at: ww("w1"),
                    repo: Repo::App,
                    branch: "proj--w1",
                }),
            kept_backup_shown(&ww("w1"), "remotes/app log ", "hand commit"),
            Step::git(&ww("w1"), Repo::App, &["log", "--format=%s", "-1", "w2"])
                .expect(Exit::Succeeds)
                .claim(Claim::OutputLine("w2-app")),
            Step::git(&ww("w1"), Repo::App, &["log", "--format=%s", "proj--w1"])
                .expect(Exit::Succeeds)
                .claim(Claim::OutputLacks("main-app")),
        ]),
        BuiltOnChoice::Continue => steps.extend([
            Step::rwv(&ww("w1"), &["land", "--continue"])
                .expect(Exit::Succeeds)
                .claim(Claim::Contains {
                    at: ww("w1"),
                    repo: Repo::App,
                    rev: "w2",
                    mark: "main-app",
                }),
            Step::git(&ww("w1"), Repo::App, &["log", "--format=%s", "-1", "w2"])
                .expect(Exit::Succeeds)
                .claim(Claim::OutputLine("hand commit")),
            Step::git(
                &ww("w1"),
                Repo::App,
                &["merge-base", "--is-ancestor", "proj--w1", "w2"],
            )
            .expect(Exit::Succeeds),
            Step::rwv(&ww("w1"), &["sync"])
                .expect(Exit::Succeeds)
                .claim(Claim::OutputLacks("lacks")),
        ]),
    }
    scenario("stack: an abort meets a carried dependent built on", steps)
}

/// What stands in the way of an abort putting a carried dependent back.
#[derive(Debug, Clone, Copy)]
pub enum CarriedBlocked {
    /// `w2` checked out in a worktree outside the op's workspaces.
    CheckedOut,
    /// `w2` checked out in the target's checkout of `app`, which the
    /// landing never moved, so abort leaves it on `w2`.
    CheckedOutInTheTarget,
    /// `w2` deleted.
    Gone,
}

/// `stack-carried-by-a-landing` killed after its carry moved `w2`, then
/// `w2` checked out elsewhere or gone: `rwv abort` puts nothing back and
/// names what to do first; once done, `rwv abort` puts everything back.
pub fn abort_a_carried_stack_blocked(blocked: CarriedBlocked) -> Scenario {
    let mut steps = stack_on_a_seat();
    steps.extend(main_moves_app("main-app"));
    steps.extend([
        Step::rwv_paused(&ww("w1"), &["land"], "composed", "landing"),
        Step::kill("landing"),
    ]);
    let (block, needs, clear) = match blocked {
        CarriedBlocked::CheckedOut => (
            Step::git(
                &ww("w1"),
                Repo::App,
                &["worktree", "add", "-q", "../../../../w2-held", "w2"],
            ),
            "is checked out at",
            Step::rwv_printed_holding(&ww("w1"), "git -C ", "switch --detach")
                .expect(Exit::Succeeds),
        ),
        CarriedBlocked::CheckedOutInTheTarget => (
            Step::git(&a(), Repo::App, &["switch", "-q", "w2"]),
            "is checked out at",
            Step::rwv_printed_holding(&ww("w1"), "git -C ", "switch --detach")
                .expect(Exit::Succeeds),
        ),
        CarriedBlocked::Gone => (
            Step::git(&ww("w1"), Repo::App, &["branch", "-q", "-D", "w2"])
                .may_leave_unresolved(&[Repo::App]),
            "put 'w2' back where this operation carried it",
            Step::rwv_printed_holding(&ww("w1"), "git -C ", "branch w2 ").expect(Exit::Succeeds),
        ),
    };
    steps.extend([
        block,
        Step::rwv(&ww("w1"), &["abort"])
            .expect(Exit::refuses_kind(RefusalKind::ForeignTip))
            .claim(Claim::OutputLacks("abort stopped there"))
            .claim(Claim::OutputContains(needs))
            .claim(Claim::OutputContains("once each fix above is made, rerun"))
            .claim(Claim::OutputLacks("--abandon-foreign-tip"))
            .claim(Claim::LocalStateUnchanged(ww("w1"))),
        clear,
        Step::rwv(&ww("w1"), &["abort"])
            .expect(Exit::Succeeds)
            .may_rewind(&[Repo::App])
            .may_restore(&[Repo::App, Repo::Proj])
            .claim(Claim::OutputLacks("foreign")),
        Step::git(&ww("w1"), Repo::App, &["log", "--format=%s", "-1", "w2"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLine("w2-app")),
        Step::git(&ww("w1"), Repo::App, &["log", "--format=%s", "w2"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLacks("main-app")),
    ]);
    scenario(
        "stack: an abort meets a carried dependent it cannot move",
        steps,
    )
}

/// Another seat's commit of `other-seat.txt` on `branch` of `repo`, written
/// from the checkout at `from` to the ref every checkout of that store
/// shares.
fn another_seat_commits(from: &Place, repo: Repo, branch: &str) -> Step {
    Step::hand_commit(from, repo, branch, &[("other-seat.txt", "other seat\n")])
}

/// After `stopped`, another seat commits from `from` on `branch` of the
/// stopped `repo` at `at`; `rwv abort` ends the operation keeping that
/// commit in the branch's `slot`, as it keeps the tip of every branch it
/// resets.
fn abort_keeps_another_seats_commit(
    stopped: Vec<Step>,
    from: Place,
    at: Place,
    repo: Repo,
    branch: &'static str,
    slot: &'static str,
) -> Vec<Step> {
    let mut steps = stopped;
    steps.extend([
        another_seat_commits(&from, repo, branch),
        Step::rwv(&at, &["abort"])
            .expect(Exit::Succeeds)
            .may_rewind(&[Repo::App, Repo::Lib, Repo::Proj])
            .may_restore(&[Repo::App, Repo::Lib, Repo::Proj])
            .claim(Claim::OutputContains("/aborted")),
        Step::git(
            &at,
            repo,
            &["log", "--format=%s", slot, "--", "other-seat.txt"],
        )
        .expect(Exit::Succeeds)
        .claim(Claim::OutputLine("hand commit")),
        Step::rwv(&at, &["abort"]).expect(Exit::refuses_kind(RefusalKind::NoOpRecorded)),
    ]);
    steps
}

/// A `linear` sync stopped at the check of its replayed project tip, whose
/// `rwv.toml` names a member `main` added back that the stop has yet to
/// place: `rwv doctor` there reports no missing worktree and its `--fix`
/// makes none; the operation's continue places it.
pub fn doctor_at_a_stop_offers_no_fix_for_a_member_the_operation_places() -> Scenario {
    let at = ww("w");
    scenario(
        "doctor at a stop offers no fix for a member the operation places",
        vec![
            create("w"),
            Step::rwv(&a(), &["member", "remove", DOCS]).expect(Exit::Succeeds),
            Step::rwv(&at, &["sync"]).expect(Exit::Succeeds),
            Step::rwv(&a(), &["member", "set-role", APP, "fork"]).expect(Exit::Succeeds),
            Step::rwv(&a(), &["member", "add", "url:origin:docs"]).expect(Exit::Succeeds),
            Step::rwv(&at, &["member", "set-recurse-submodules", APP, "false"])
                .expect(Exit::Succeeds),
            Step::rwv(&at, &["sync", "--history", "linear"]).expect(Exit::refuses(
                Repo::Proj,
                State::UnparseableProjectMidOperation,
            )),
            Step::rwv(&at, &["doctor"])
                .expect(Exit::Succeeds)
                .claim(Claim::OutputLacks("local/remotes/docs"))
                .claim(Claim::OutputContains("stale-op-state")),
            Step::rwv(&at, &["doctor", "--fix"])
                .expect(Exit::Succeeds)
                .claim(Claim::OutputLacks("local/remotes/docs")),
            Step::rwv(&at, &["sync", "--continue", "--keep", "text-merge"])
                .expect(Exit::Succeeds)
                .may_strand(&[Repo::Proj]),
            Step::git(&at, Repo::Docs, &["rev-parse", "HEAD"]).expect(Exit::Succeeds),
        ],
    )
}

/// A sync that prunes a member `main` dropped, then one under `history`
/// that gives the workweave a checkout of it once `main` adds it back: each
/// ends with no savepoint of its operation left in the member's store, the
/// pruned checkout's included.
pub fn a_sync_taking_in_an_added_member_leaves_no_savepoint(history: &'static str) -> Scenario {
    scenario(
        match history {
            "linear" => "a linear sync taking in an added member leaves no savepoint",
            _ => "a merge sync taking in an added member leaves no savepoint",
        },
        vec![
            create("w"),
            Step::rwv(&a(), &["member", "remove", DOCS]).expect(Exit::Succeeds),
            Step::rwv(&ww("w"), &["sync"]).expect(Exit::Succeeds),
            Step::git(&a(), Repo::Docs, &["for-each-ref", "refs/rwv/pre-op"])
                .expect(Exit::Succeeds)
                .claim(Claim::OutputLacks("refs/rwv/pre-op")),
            Step::rwv(&a(), &["member", "add", "url:origin:docs"]).expect(Exit::Succeeds),
            Step::rwv(&ww("w"), &["sync", "--history", history]).expect(Exit::Succeeds),
            Step::git(&ww("w"), Repo::Docs, &["for-each-ref", "refs/rwv/pre-op"])
                .expect(Exit::Succeeds)
                .claim(Claim::OutputLacks("refs/rwv/pre-op")),
        ],
    )
}

/// A port stopped on `app`'s copy, which the operator finishes with the
/// VCS and then commits on: `--continue` finds the finished copy below the
/// hand commit, takes both in, and copies nothing again.
pub fn cherry_pick_continue_takes_in_a_finished_copy_under_a_hand_commit() -> Scenario {
    let mut steps = app_conflicting_port();
    steps.extend([
        Step::git(&ww("p"), Repo::App, &["checkout", "--theirs", "README"]),
        Step::hand_edit(&ww("p"), Repo::App, "README", "app on main", "app resolved"),
        Step::git(&ww("p"), Repo::App, &["add", "README"]),
        Step::git(
            &ww("p"),
            Repo::App,
            &["-c", "core.editor=true", "cherry-pick", "--continue"],
        ),
        Step::commit(&ww("p"), Repo::App, "hand-at-stop"),
        Step::rwv(&ww("p"), &["cherry-pick", "--continue"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLacks("stopped on a conflict"))
            .claim(Claim::Contains {
                at: ww("p"),
                repo: Repo::App,
                rev: "proj--p",
                mark: "hand-at-stop",
            }),
        Step::git(
            &ww("p"),
            Repo::App,
            &["log", "-1", "--format=%s", "proj--p"],
        )
        .expect(Exit::Succeeds)
        .claim(Claim::OutputLine("hand-at-stop")),
    ]);
    scenario(
        "cherry-pick --continue takes in a finished copy under a hand commit",
        steps,
    )
}

/// `pull --merge-upstream` stopped on `app`'s merge, which the operator
/// resolves and commits by hand: `--continue` takes that commit in, and the
/// project's merge pins `app` at it rather than at one side's tip.
pub fn pull_continue_pins_a_member_merge_committed_by_hand() -> Scenario {
    let mut steps = both_sides_move_app_conflictingly();
    steps.extend([
        Step::git(&b(), Repo::App, &["checkout", "--ours", "README"]),
        Step::git(&b(), Repo::App, &["add", "README"]),
        Step::git(&b(), Repo::App, &["commit", "-q", "-m", "hand-merge"]),
        Step::rwv(&b(), &["pull", "--continue"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLacks("neither contains the other"))
            .claim(Claim::PinsReplayed {
                at: b(),
                rev: "HEAD",
                member: Repo::App,
                subject: "hand-merge",
                reached_from: "main",
            }),
    ]);
    scenario(
        "pull --continue pins a member merge committed by hand",
        steps,
    )
}

/// Which operation [`a_stop_marked_resolved_continues`] stops on `app`.
#[derive(Debug, Clone, Copy)]
pub enum StoppedOnApp {
    SyncLinear,
    SyncMerge,
    LandLinear,
    LandMerge,
    Pull,
    CherryPick,
    UpdateRemote,
}

/// An operation stopped on a conflict in `app`, whose stop prints marking
/// the file resolved and then its `--continue`. Done as printed, the
/// continue finishes the operation and leaves nothing to abort.
pub fn a_stop_marked_resolved_continues(which: StoppedOnApp) -> Scenario {
    use StoppedOnApp as S;
    let (mut steps, at, resume, printed, side): (Vec<Step>, Place, &[&str], &'static str, &str) =
        match which {
            S::SyncLinear | S::SyncMerge => {
                let mut stopped = sync_stopped_on_app_resolved(match which {
                    S::SyncLinear => "linear",
                    _ => "merge",
                });
                stopped.truncate(stopped.len() - 2);
                (
                    stopped,
                    ww("w"),
                    &["sync", "--continue"],
                    "rwv sync --continue",
                    "--ours",
                )
            }
            S::LandLinear => (
                land_linear_stopped_on_app(),
                ww("w"),
                &["land", "--continue"],
                "rwv land --continue",
                "--ours",
            ),
            S::LandMerge => (
                landing_merge_stopped(),
                ww("w"),
                &["land", "--continue"],
                "rwv land --continue",
                "--ours",
            ),
            S::Pull => (
                both_sides_move_app_conflictingly(),
                b(),
                &["pull", "--continue"],
                "then run `rwv pull --continue`",
                "--ours",
            ),
            S::CherryPick => (
                app_conflicting_port(),
                ww("p"),
                &["cherry-pick", "--continue"],
                "rwv cherry-pick --continue",
                "--theirs",
            ),
            S::UpdateRemote => (
                update_remote_stopped_on_a_conflict(),
                a(),
                &["update", "--remote", "--continue"],
                "then run `rwv update --remote --continue`",
                "--ours",
            ),
        };
    let stop = steps
        .iter()
        .rposition(|step| {
            matches!(
                step.expect.exit,
                Exit::Refuses(super::runner::Refusal::Kind(RefusalKind::OpParked))
            )
        })
        .expect("the stop");
    steps[stop].expect.claims.extend([
        Claim::OutputContains("git add <files>"),
        Claim::OutputContains(printed),
    ]);
    steps.extend([
        Step::git(&at, Repo::App, &["checkout", side, "README"]),
        Step::git(&at, Repo::App, &["add", "README"]),
        Step::rwv(&at, resume)
            .expect(Exit::Succeeds)
            .may_strand(&[Repo::App, Repo::Lib, Repo::Proj])
            .may_rewind(&[Repo::App]),
        Step::rwv(&at, &["abort"]).expect(Exit::refuses_kind(RefusalKind::NoOpRecorded)),
    ]);
    scenario(
        match which {
            S::SyncLinear => "a linear sync stop marked resolved continues",
            S::SyncMerge => "a merge sync stop marked resolved continues",
            S::LandLinear => "a linear landing stop marked resolved continues",
            S::LandMerge => "a merge landing stop marked resolved continues",
            S::Pull => "a pull stop marked resolved continues",
            S::CherryPick => "a cherry-pick stop marked resolved continues",
            S::UpdateRemote => "an update --remote stop marked resolved continues",
        },
        steps,
    )
}

/// Which stopped operation [`continue_after_another_seat_moves`] resumes,
/// and which of its repos another seat moves during the stop.
#[derive(Debug, Clone, Copy)]
pub enum StoppedMoved {
    LandProject,
    LandMember,
    PullProject,
    PullMember,
    CherryPickProject,
    CherryPickMember,
}

/// An operation stopped on `app` and resolved; during the stop another
/// seat commits on the branch of a repo the operation has yet to take in
/// or commit. The continue finishes with that commit on the branch and its
/// file in the checkout, never committing its reverse.
pub fn continue_after_another_seat_moves(which: StoppedMoved) -> Scenario {
    use StoppedMoved as S;
    let resolve = |at: &Place, side: &'static str| {
        [
            Step::git(at, Repo::App, &["checkout", side, "README"]),
            Step::git(at, Repo::App, &["add", "README"]),
        ]
    };
    let (mut steps, from, at, repo, branch, resume): (
        Vec<Step>,
        Place,
        Place,
        Repo,
        &str,
        &[&str],
    ) = match which {
        S::LandProject | S::LandMember => (
            land_linear_stopped_on_app(),
            a(),
            ww("w"),
            if matches!(which, S::LandProject) {
                Repo::Proj
            } else {
                Repo::Lib
            },
            "proj--w",
            &["land", "--continue"],
        ),
        S::PullProject | S::PullMember => {
            let mut stopped = both_sides_move_app_conflictingly();
            stopped.splice(
                1..1,
                [
                    Step::rwv(&b(), &["member", "remove", DOCS]).expect(Exit::Succeeds),
                    Step::rwv(&b(), &["workweave", "create", "--project", "proj", "o"])
                        .expect(Exit::Succeeds),
                ],
            );
            (
                stopped,
                Place::ww(Machine::B, "o"),
                b(),
                if matches!(which, S::PullProject) {
                    Repo::Proj
                } else {
                    Repo::Lib
                },
                "main",
                &["pull", "--continue"],
            )
        }
        S::CherryPickProject | S::CherryPickMember => (
            app_conflicting_port(),
            a(),
            ww("p"),
            if matches!(which, S::CherryPickProject) {
                Repo::Proj
            } else {
                Repo::Lib
            },
            "proj--p",
            &["cherry-pick", "--continue"],
        ),
    };
    let side = match which {
        S::CherryPickProject | S::CherryPickMember => "--theirs",
        _ => "--ours",
    };
    steps.extend(resolve(&at, side));
    steps.extend([
        another_seat_commits(&from, repo, branch),
        Step::rwv(&at, resume)
            .expect(Exit::Succeeds)
            .may_strand(&[Repo::App, Repo::Lib, Repo::Proj])
            .may_rewind(&[Repo::App]),
        Step::git(
            &at,
            repo,
            &["cat-file", "-e", &format!("{branch}:other-seat.txt")],
        )
        .expect(Exit::Succeeds),
        Step::git(&at, repo, &["status", "--porcelain"])
            .expect(Exit::Succeeds)
            .claim(Claim::OutputLacks("other-seat.txt")),
    ]);
    scenario(
        match which {
            S::LandProject => "land --continue after another seat moved the project",
            S::LandMember => "land --continue after another seat moved a member",
            S::PullProject => "pull --continue after another seat moved the project",
            S::PullMember => "pull --continue after another seat moved a member",
            S::CherryPickProject => "cherry-pick --continue after another seat moved the project",
            S::CherryPickMember => "cherry-pick --continue after another seat moved a member",
        },
        steps,
    )
}

/// Which operation [`continue_refuses_a_stopped_repo_moved`] stops in a
/// merge or copy, and how it is resumed.
#[derive(Debug, Clone, Copy)]
pub enum StoppedMidMerge {
    /// A `merge` sync's member merge, resolved, resumed bare.
    SyncMember,
    /// [`StoppedMidMerge::SyncMember`], the checkout's record of where it
    /// stood gone once the branch moved.
    SyncMemberUnrecorded,
    /// A `merge` sync's project merge on `rwv.toml`, resumed with
    /// `--keep yours`.
    SyncProjectKeepYours,
    /// A `merge` landing's member merge, resolved.
    LandMember,
    /// `pull --merge-upstream`'s member merge, resolved.
    PullMember,
    /// A port's copy into a member, resolved.
    CherryPickMember,
    /// `update --remote --merge-upstream`'s member merge, resolved.
    UpdateRemoteMember,
}

/// An operation stopped in a merge or copy; during the stop another seat
/// commits on the stopped repo's branch. Concluding the merge or copy would
/// record that commit's reverse, so the continue refuses, naming abandoning
/// the operation, and changes nothing; that choice, run as printed, keeps
/// the commit in the branch's slot.
pub fn continue_refuses_a_stopped_repo_moved(which: StoppedMidMerge) -> Scenario {
    use StoppedMidMerge as S;
    let (mut steps, from, at, repo, branch, resume): (
        Vec<Step>,
        Place,
        Place,
        Repo,
        &'static str,
        &[&str],
    ) = match which {
        S::SyncMember | S::SyncMemberUnrecorded => (
            sync_stopped_on_app_resolved("merge"),
            a(),
            ww("w"),
            Repo::App,
            "proj--w",
            &["sync", "--continue"],
        ),
        S::SyncProjectKeepYours => (
            sync_stopped_on_the_manifest("merge"),
            a(),
            ww("w"),
            Repo::Proj,
            "proj--w",
            &["sync", "--continue", "--keep", "yours"],
        ),
        S::LandMember => {
            let mut stopped = landing_merge_stopped();
            stopped.extend([
                Step::git(&ww("w"), Repo::App, &["checkout", "--ours", "README"]),
                Step::git(&ww("w"), Repo::App, &["add", "README"]),
            ]);
            (
                stopped,
                a(),
                ww("w"),
                Repo::App,
                "proj--w",
                &["land", "--continue"],
            )
        }
        S::PullMember => {
            let mut stopped = both_sides_move_app_conflictingly();
            stopped.splice(
                1..1,
                [
                    Step::rwv(&b(), &["member", "remove", DOCS]).expect(Exit::Succeeds),
                    Step::rwv(&b(), &["workweave", "create", "--project", "proj", "o"])
                        .expect(Exit::Succeeds),
                ],
            );
            stopped.extend([
                Step::git(&b(), Repo::App, &["checkout", "--ours", "README"]),
                Step::git(&b(), Repo::App, &["add", "README"]),
            ]);
            (
                stopped,
                Place::ww(Machine::B, "o"),
                b(),
                Repo::App,
                "main",
                &["pull", "--continue"],
            )
        }
        S::CherryPickMember => {
            let mut stopped = app_conflicting_port();
            stopped.extend([
                Step::git(&ww("p"), Repo::App, &["checkout", "--theirs", "README"]),
                Step::git(&ww("p"), Repo::App, &["add", "README"]),
            ]);
            (
                stopped,
                a(),
                ww("p"),
                Repo::App,
                "proj--p",
                &["cherry-pick", "--continue"],
            )
        }
        S::UpdateRemoteMember => {
            let mut stopped = update_remote_stopped_on_a_conflict();
            stopped.insert(1, create("o"));
            stopped.extend([
                Step::git(&a(), Repo::App, &["checkout", "--ours", "README"]),
                Step::git(&a(), Repo::App, &["add", "README"]),
            ]);
            (
                stopped,
                ww("o"),
                a(),
                Repo::App,
                "main",
                &["update", "--remote", "--continue"],
            )
        }
    };
    let slot = format!("refs/rwv/backup/{branch}/aborted");
    steps.push(another_seat_commits(&from, repo, branch));
    if matches!(which, S::SyncMemberUnrecorded) {
        steps.push(Step::git(
            &at,
            repo,
            &["reflog", "expire", "--expire=now", "--all"],
        ));
    }
    steps.extend([
        Step::rwv(&at, resume)
            .expect(Exit::refuses(repo, State::EditsDriftLeftInPlace))
            .claim(Claim::OutputContains("outside this checkout while the"))
            .claim(Claim::LocalStateUnchanged(at.clone())),
        Step::rwv_printed_exactly(&at, "rwv abort")
            .expect(Exit::Succeeds)
            .may_rewind(&[Repo::App, Repo::Lib, Repo::Proj])
            .may_restore(&[Repo::App, Repo::Lib, Repo::Proj]),
        Step::git(
            &at,
            repo,
            &["log", "--format=%s", &slot, "--", "other-seat.txt"],
        )
        .expect(Exit::Succeeds)
        .claim(Claim::OutputLine("hand commit")),
    ]);
    scenario(
        match which {
            S::SyncMember => "sync --continue refuses a member moved mid-merge",
            S::SyncMemberUnrecorded => {
                "sync --continue refuses a member moved mid-merge with no record of where it stood"
            }
            S::SyncProjectKeepYours => {
                "sync --continue --keep yours refuses the project moved mid-merge"
            }
            S::LandMember => "land --continue refuses a member moved mid-merge",
            S::PullMember => "pull --continue refuses a member moved mid-merge",
            S::CherryPickMember => "cherry-pick --continue refuses a member moved mid-copy",
            S::UpdateRemoteMember => "update --remote --continue refuses a member moved mid-merge",
        },
        steps,
    )
}

/// A `linear` sync stopped mid-rebase of `lib`, a commit of another seat's
/// on `lib`'s branch, aborted.
pub fn sync_abort_keeps_another_seats_commit() -> Scenario {
    scenario(
        "sync abort keeps another seat's commit on a branch stopped mid-rebase",
        abort_keeps_another_seats_commit(
            sync_linear_stopped_on_lib(),
            a(),
            ww("w"),
            Repo::Lib,
            "proj--w",
            "refs/rwv/backup/proj--w/aborted",
        ),
    )
}

/// A `linear` sync of `w` stopped on its project repo's `rwv.toml`, where
/// both sides set `lib`'s `history`.
fn sync_linear_stopped_on_the_manifest() -> Vec<Step> {
    sync_stopped_on_the_manifest("linear")
}

/// A sync of `w` under `history` stopped on its project repo's `rwv.toml`,
/// where `main` sets `lib`'s `history` to `history` and `w` to the other.
fn sync_stopped_on_the_manifest(history: &'static str) -> Vec<Step> {
    let other = match history {
        "linear" => "merge",
        _ => "linear",
    };
    vec![
        create("w"),
        Step::rwv(&a(), &["branch", "set-history", history, "--repo", LIB]).expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &["branch", "set-history", other, "--repo", LIB])
            .expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &["sync", "--history", history])
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .claim(Claim::OutputContains(
                "rwv.toml entry local/remotes/lib is in conflict:",
            )),
    ]
}

