/// `proj`'s committed `rwv.toml` holding its member tables as lib, app, docs:
/// an order a hand edit leaves and no serializer writes.
fn hand_ordered_manifest() -> Vec<Step> {
    vec![
        Step::reorder_manifest(&a(), &[Repo::Lib, Repo::App, Repo::Docs]),
        Step::git(&a(), Repo::Proj, &["commit", "-qam", "hand: reorder"]),
    ]
}

/// On a hand-ordered `rwv.toml`, a setter on each side changes a different
/// member. Each side's commit is only its own line, so the sync takes both in
/// as one manifest that lists every member once.
pub fn a_hand_ordered_manifest_takes_in_a_setter_from_each_side(history: &'static str) -> Scenario {
    let mut steps = hand_ordered_manifest();
    steps.extend([
        create("w"),
        Step::rwv(&a(), &["member", "set-role", APP, "fork"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &["member", "set-role", DOCS, "fork"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &["sync", "--history", history])
            .expect(Exit::Succeeds)
            .claim(Claim::ManifestLists {
                at: ww("w"),
                rev: "HEAD",
                members: &[Repo::App, Repo::Lib, Repo::Docs],
            }),
    ]);
    scenario(
        "a hand-ordered manifest takes in a setter from each side",
        steps,
    )
}

/// On a hand-ordered `rwv.toml`, the workweave removes a member and the
/// primary sets another's role. The sync takes the role in and the removal
/// stays.
pub fn a_hand_ordered_manifest_keeps_a_removal_across_a_setter(history: &'static str) -> Scenario {
    let mut steps = hand_ordered_manifest();
    steps.extend([
        create("w"),
        Step::rwv(&a(), &["member", "set-role", APP, "fork"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &["member", "remove", LIB]).expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &["sync", "--history", history])
            .expect(Exit::Succeeds)
            .claim(Claim::ManifestLists {
                at: ww("w"),
                rev: "HEAD",
                members: &[Repo::App, Repo::Docs],
            }),
    ]);
    scenario(
        "a hand-ordered manifest keeps a removal across a setter",
        steps,
    )
}

/// On a hand-ordered `rwv.toml` with no `[repositories]` header and an
/// integration table between its two member tables, the primary and the
/// workweave each remove one of the members. Git's merge of the two holds no
/// `repositories` table, which is no manifest: the sync stops, and once the
/// bare table is declared and staged, the continue ends with no members.
pub fn removals_from_both_sides_that_leave_no_member_sync_into_an_empty_manifest(
    history: &'static str,
) -> Scenario {
    let integration = "[integrations.vscode-workspace]\nenabled = false\n";
    let app_header = format!("[repositories.\"{}\"]", Repo::App.rel_path());
    let mut steps = hand_ordered_manifest();
    steps.extend([
        Step::rwv(&a(), &["member", "remove", DOCS]).expect(Exit::Succeeds),
        Step::hand_edit(
            &a(),
            Repo::Proj,
            "rwv.toml",
            &format!("\n{integration}"),
            "",
        ),
        Step::hand_edit(
            &a(),
            Repo::Proj,
            "rwv.toml",
            &app_header,
            &format!("{integration}\n{app_header}"),
        ),
        Step::git(
            &a(),
            Repo::Proj,
            &["commit", "-qam", "hand: split the members"],
        ),
        create("w"),
        Step::rwv(&a(), &["member", "remove", LIB]).expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &["member", "remove", APP]).expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &["sync", "--history", history])
            .expect(Exit::refuses(
                Repo::Proj,
                State::UnparseableProjectMidOperation,
            ))
            .claim(Claim::OutputContains("holds no `repositories` table"))
            .claim(Claim::OutputContains("add the line `[repositories]`")),
        Step::hand_edit(
            &ww("w"),
            Repo::Proj,
            "rwv.toml",
            "[integrations.vscode-workspace]",
            "[repositories]\n\n[integrations.vscode-workspace]",
        ),
        Step::rwv_printed_holding(&ww("w"), "git -C ", "add -- rwv.toml").expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &["sync", "--continue"])
            .expect(Exit::Succeeds)
            .may_strand(if history == "linear" {
                &[Repo::Proj]
            } else {
                &[]
            })
            .claim(Claim::ManifestLists {
                at: ww("w"),
                rev: "HEAD",
                members: &[],
            }),
    ]);
    scenario(
        "removals from both sides that leave no member stop until the empty table is declared",
        steps,
    )
}

/// The table each side adds to `rwv.toml` by hand: `a`'s right under the
/// integrations table, the workweave's above `docs`'s entry. Git merges the
/// two as text without a conflict into a file holding `[workweave]` twice.
const A_COPIES: &str = "[workweave]\ncopy = [\"a.txt\"]\n";
const W_COPIES: &str = "\n[workweave]\ncopy = [\"w.txt\"]\n";
const UNDER_INTEGRATIONS: &str = "enabled = false\n";
const ABOVE_DOCS: &str = "\n[repositories.\"local/remotes/docs\"]";

fn adds_a_copies(at: &Place) -> Vec<Step> {
    vec![
        Step::hand_edit(
            at,
            Repo::Proj,
            "rwv.toml",
            UNDER_INTEGRATIONS,
            "enabled = false\n\n[workweave]\ncopy = [\"a.txt\"]\n",
        ),
        Step::git(at, Repo::Proj, &["commit", "-qam", "copy a.txt"]),
    ]
}

fn adds_w_copies(at: &Place) -> Vec<Step> {
    vec![
        Step::hand_edit(
            at,
            Repo::Proj,
            "rwv.toml",
            ABOVE_DOCS,
            "\n[workweave]\ncopy = [\"w.txt\"]\n\n[repositories.\"local/remotes/docs\"]",
        ),
        Step::git(at, Repo::Proj, &["commit", "-qam", "copy w.txt"]),
    ]
}

/// How a stop on an unparseable merged `rwv.toml` is left.
#[derive(Clone, Copy)]
pub enum LeftBy {
    /// A `--continue` before any fix, an edit left unstaged, then the
    /// printed staging and continue.
    StagedFix,
    /// The printed `rwv abort`.
    Abort,
    /// `rwv abort` run in the landing's target, which reads the source's
    /// `rwv.toml` from the other side.
    AbortInTheTarget,
}

/// Which verb takes the other side's `rwv.toml` in, under which history.
#[derive(Clone, Copy)]
pub enum TakingIn {
    SyncLinear,
    SyncMerge,
    LandLinear,
    LandMerge,
}

impl TakingIn {
    fn args(self) -> [&'static str; 3] {
        match self {
            Self::SyncLinear => ["sync", "--history", "linear"],
            Self::SyncMerge => ["sync", "--history", "merge"],
            Self::LandLinear => ["land", "--history", "linear"],
            Self::LandMerge => ["land", "--history", "merge"],
        }
    }

    fn resume(self) -> &'static str {
        match self {
            Self::SyncLinear | Self::SyncMerge => "rwv sync --continue",
            Self::LandLinear | Self::LandMerge => "rwv land --continue",
        }
    }

    fn says(self) -> &'static str {
        match self {
            Self::SyncLinear | Self::LandLinear => "the replay finished",
            Self::SyncMerge | Self::LandMerge => "the merge is in progress",
        }
    }

    fn linear(self) -> bool {
        matches!(self, Self::SyncLinear | Self::LandLinear)
    }

    fn lands(self) -> bool {
        matches!(self, Self::LandLinear | Self::LandMerge)
    }
}

/// What a stop on an unparseable merged `rwv.toml` leaves: `a`'s `main` not
/// holding the workweave's work, the stop's own line, and its choices in
/// order.
fn stops_unparseable(step: Step, says: &'static str) -> Step {
    step.expect(Exit::refuses(
        Repo::Proj,
        State::UnparseableProjectMidOperation,
    ))
    .claim(Claim::OutputContains(says))
    .claim(Claim::OutputContains("duplicate key"))
    .claim(Claim::OutputInOrder(&[
        "choices:",
        "add -- rwv.toml",
        "--continue",
        "rwv abort",
    ]))
    .claim(Claim::Lacks {
        at: a(),
        repo: Repo::Proj,
        rev: "main",
        mark: "w-proj",
    })
}

/// Each side adds a `[workweave]` table to `rwv.toml` by hand, the
/// workweave's in one commit, and the workweave takes `a`'s in by
/// `taking_in`: git merges the two as text without a conflict into a file
/// that does not parse, and the operation stops on it with `main` unmoved.
/// Left by `left_by`: a staged fix that parses finishes it, the fix part of
/// the replayed commit under linear history and in the merge under merge
/// history, so no commit the operation leaves holds an `rwv.toml` that does
/// not parse and `rwv cherry-pick` copies the landed commit; or the printed
/// `rwv abort` puts the workweave back with no merge in flight and nothing
/// staged.
pub fn unparseable_merged_manifest(taking_in: TakingIn, left_by: LeftBy) -> Scenario {
    let mut steps = vec![create("p"), create("w")];
    steps.extend(adds_a_copies(&a()));
    steps.push(Step::commit(&a(), Repo::Proj, "a-proj"));
    steps.extend([
        Step::hand_edit(
            &ww("w"),
            Repo::Proj,
            "rwv.toml",
            ABOVE_DOCS,
            "\n[workweave]\ncopy = [\"w.txt\"]\n\n[repositories.\"local/remotes/docs\"]",
        ),
        Step::git(&ww("w"), Repo::Proj, &["add", "rwv.toml"]),
        Step::commit(&ww("w"), Repo::Proj, "w-proj"),
    ]);
    steps.push(stops_unparseable(
        Step::rwv(&ww("w"), &taking_in.args()),
        taking_in.says(),
    ));
    match left_by {
        LeftBy::AbortInTheTarget => steps.extend(aborted_from(
            Step::rwv(&a(), &["abort"]).claim(Claim::OutputLacks("finished by hand")),
            &ww("w"),
            &[],
        )),
        LeftBy::StagedFix => {
            steps.push(stops_unparseable(
                Step::rwv_printed(&ww("w"), taking_in.resume()),
                taking_in.says(),
            ));
            steps.push(Step::hand_edit(
                &ww("w"),
                Repo::Proj,
                "rwv.toml",
                W_COPIES,
                "",
            ));
            steps.push(stops_unparseable(
                Step::rwv_printed(&ww("w"), taking_in.resume()),
                taking_in.says(),
            ));
            steps.push(Step::rwv_printed(&ww("w"), "git -C ").expect(Exit::Succeeds));
            steps.extend(working_file_breaks_a_staged_fix(
                &ww("w"),
                taking_in.args()[0],
            ));
            let finished = Step::rwv(&ww("w"), &[taking_in.args()[0], "--continue"])
                .expect(Exit::Succeeds)
                .may_strand(if taking_in.linear() {
                    &[Repo::Proj]
                } else {
                    &[]
                })
                .claim(Claim::Contains {
                    at: ww("w"),
                    repo: Repo::Proj,
                    rev: "HEAD",
                    mark: "a-proj",
                });
            steps.push(finished);
            steps.push(
                Step::git(&ww("w"), Repo::Proj, &["log", "--format=%s", "-5"])
                    .claim(Claim::OutputContains("w-proj")),
            );
            steps.push(
                Step::git(&ww("w"), Repo::Proj, &["show", "HEAD:rwv.toml"])
                    .claim(Claim::OutputContains(A_COPIES))
                    .claim(Claim::OutputLacks("w.txt")),
            );
            steps.push(
                Step::git(&ww("w"), Repo::Proj, &["status", "--porcelain"])
                    .claim(Claim::OutputLacks("rwv.toml")),
            );
            if taking_in.linear() {
                steps.extend([
                    Step::git(&ww("w"), Repo::Proj, &["log", "--format=%s", "-1"])
                        .claim(Claim::OutputLine("w-proj")),
                    Step::git(&ww("w"), Repo::Proj, &["log", "--format=%s", "-2"])
                        .claim(Claim::OutputContains("a-proj")),
                    Step::git(&ww("w"), Repo::Proj, &["show", "HEAD~1:rwv.toml"])
                        .claim(Claim::OutputLacks("w.txt")),
                ]);
            }
            if taking_in.lands() {
                steps.extend([
                    Step::git(&a(), Repo::Proj, &["log", "--format=%s", "-5", "main"])
                        .claim(Claim::OutputContains("w-proj")),
                    Step::git(&a(), Repo::Proj, &["show", "main:rwv.toml"])
                        .claim(Claim::OutputContains(A_COPIES))
                        .claim(Claim::OutputLacks("w.txt")),
                ]);
            }
            if taking_in.lands() && taking_in.linear() {
                steps.extend([
                    Step::rwv(&ww("p"), &["cherry-pick", "main"]).expect(Exit::Succeeds),
                    Step::git(&ww("p"), Repo::Proj, &["show", "HEAD:w-proj.txt"])
                        .expect(Exit::Succeeds),
                    Step::rwv(&a(), &["switch", "--detach", "main"]).expect(Exit::Succeeds),
                    Step::rwv(&a(), &["switch", "main"]).expect(Exit::Succeeds),
                ]);
            }
        }
        LeftBy::Abort => steps.extend(aborted_to_the_workweaves_own(&ww("w"), &[])),
    }
    scenario(
        "an unparseable merged rwv.toml is left by its printed choices",
        steps,
    )
}

/// At a stop on an unparseable `rwv.toml` with a fix that parses staged, the
/// working file edited again so that it does not parse: `verb`'s
/// `--continue` refuses in
/// the same state, saying the working file differs from what is staged,
/// before anything is committed; with the edit undone the stop is as it was.
fn working_file_breaks_a_staged_fix(at: &Place, verb: &'static str) -> Vec<Step> {
    let broken = "enabled = false\n[[[\n";
    vec![
        Step::hand_edit(at, Repo::Proj, "rwv.toml", UNDER_INTEGRATIONS, broken),
        Step::rwv(at, &[verb, "--continue"])
            .expect(Exit::refuses(
                Repo::Proj,
                State::UnparseableProjectMidOperation,
            ))
            .claim(Claim::OutputContains(
                "the working rwv.toml differs from the resolved one",
            ))
            .claim(Claim::OutputContains("[[["))
            .claim(Claim::LocalStateUnchanged(at.clone())),
        Step::hand_edit(at, Repo::Proj, "rwv.toml", broken, UNDER_INTEGRATIONS),
    ]
}

/// The printed `rwv abort`, run at `at`, putting back the members in `moved`
/// too: the project repo is back on its own commit, with no merge in flight
/// and nothing staged, and `a`'s `main` does not hold the workweave's work.
/// The replay was rwv's alone, so none of it is kept as finished by hand.
fn aborted_to_the_workweaves_own(at: &Place, moved: &[Repo]) -> Vec<Step> {
    aborted_from(
        Step::rwv_printed(at, "rwv abort").claim(Claim::OutputLacks("finished by hand")),
        at,
        moved,
    )
}

/// [`aborted_to_the_workweaves_own`] by `abort`, run wherever it runs.
fn aborted_from(abort: Step, at: &Place, moved: &[Repo]) -> Vec<Step> {
    let restored: Vec<Repo> = std::iter::once(Repo::Proj)
        .chain(moved.iter().copied())
        .collect();
    vec![
        abort
            .expect(Exit::Succeeds)
            .may_restore(&restored)
            .may_rewind(moved)
            .claim(Claim::Lacks {
                at: at.clone(),
                repo: Repo::Proj,
                rev: "HEAD",
                mark: "a-proj",
            })
            .claim(Claim::Lacks {
                at: a(),
                repo: Repo::Proj,
                rev: "main",
                mark: "w-proj",
            }),
        Step::git(
            at,
            Repo::Proj,
            &["rev-parse", "-q", "--verify", "MERGE_HEAD"],
        )
        .expect(Exit::Code(1)),
        Step::git(at, Repo::Proj, &["status", "--porcelain"]).claim(Claim::OutputLacks("rwv")),
        Step::git(at, Repo::Proj, &["show", "HEAD:rwv.toml"])
            .claim(Claim::OutputContains("w.txt"))
            .claim(Claim::OutputLacks("a.txt")),
    ]
}

/// [`unparseable_merged_manifest`] for `rwv pull --merge-upstream` on machine
/// B, whose `main` added its table while `a` pushed the other.
pub fn unparseable_merged_manifest_pulled(left_by: LeftBy) -> Scenario {
    let mut steps = vec![Step::new_machine(Machine::B)];
    steps.extend(adds_a_copies(&a()));
    steps.push(Step::commit(&a(), Repo::Proj, "a-proj"));
    steps.push(
        Step::git(&a(), Repo::Proj, &["push", "origin", "main"])
            .pushes(Remote::origin(Repo::Proj), "main"),
    );
    steps.extend(adds_w_copies(&b()));
    steps.push(Step::commit(&b(), Repo::Proj, "w-proj"));
    let says = "the merge is in progress";
    steps.push(stops_unparseable(
        Step::rwv(&b(), &["pull", "--merge-upstream"]),
        says,
    ));
    match left_by {
        LeftBy::StagedFix => {
            steps.extend([
                stops_unparseable(Step::rwv_printed(&b(), "rwv pull --continue"), says),
                Step::hand_edit(&b(), Repo::Proj, "rwv.toml", W_COPIES, ""),
                stops_unparseable(Step::rwv_printed(&b(), "rwv pull --continue"), says),
                Step::rwv_printed(&b(), "git -C ").expect(Exit::Succeeds),
            ]);
            steps.extend(working_file_breaks_a_staged_fix(&b(), "pull"));
            steps.extend([
                Step::rwv(&b(), &["pull", "--continue"])
                    .expect(Exit::Succeeds)
                    .claim(Claim::Contains {
                        at: b(),
                        repo: Repo::Proj,
                        rev: "HEAD",
                        mark: "a-proj",
                    })
                    .claim(Claim::Contains {
                        at: b(),
                        repo: Repo::Proj,
                        rev: "HEAD",
                        mark: "w-proj",
                    }),
                Step::git(&b(), Repo::Proj, &["show", "HEAD:rwv.toml"])
                    .claim(Claim::OutputContains(A_COPIES))
                    .claim(Claim::OutputLacks("w.txt")),
            ]);
        }
        LeftBy::Abort | LeftBy::AbortInTheTarget => {
            steps.extend(aborted_to_the_workweaves_own(&b(), &[]))
        }
    }
    scenario(
        "an unparseable rwv.toml merged by pull is left by its printed choices",
        steps,
    )
}

const ABOVE_APP: &str = "[repositories.\"local/remotes/app\"]";

/// What the target changes in the member set before the workweave takes it
/// in and stops on an unparseable `rwv.toml`.
#[derive(Clone, Copy)]
pub enum TargetMembers {
    /// `a` adds `docs`, which the workweave does not list.
    Adds,
    /// `a` removes `lib`, which the workweave lists, by hand, so the rest of
    /// its `rwv.toml` keeps its order.
    Removes,
}

/// The target changes its member set and moves `app`, both sides add a
/// `[workweave]` table, and `rwv sync --history linear` stops on the
/// unparseable result having moved `app`. `rwv abort` reads no member set
/// from the `rwv.toml` at the tip it stopped on: it puts the project branch
/// and `app` back at their savepoints, and leaves the checkouts and lock as
/// the workweave had them.
pub fn abort_restores_members_past_an_unparseable_manifest(change: TargetMembers) -> Scenario {
    let mut steps = Vec::new();
    if let TargetMembers::Adds = change {
        steps.push(Step::rwv(&a(), &["member", "remove", DOCS]).expect(Exit::Succeeds));
    }
    steps.push(create("w"));
    match change {
        TargetMembers::Adds => steps
            .push(Step::rwv(&a(), &["member", "add", "url:origin:docs"]).expect(Exit::Succeeds)),
        TargetMembers::Removes => steps.extend([
            Step::drop_manifest_entry(&a(), Repo::Proj, Repo::Lib),
            Step::drop_lock_entry(&a(), Repo::Proj, Repo::Lib),
            Step::git(&a(), Repo::Proj, &["commit", "-qam", "remove lib"]),
        ]),
    }
    steps.extend([
        Step::commit(&a(), Repo::App, "a-app"),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
    ]);
    steps.extend(adds_a_copies(&a()));
    steps.push(Step::commit(&a(), Repo::Proj, "a-proj"));
    steps.extend([
        Step::hand_edit(
            &ww("w"),
            Repo::Proj,
            "rwv.toml",
            ABOVE_APP,
            "[workweave]\ncopy = [\"w.txt\"]\n\n[repositories.\"local/remotes/app\"]",
        ),
        Step::git(&ww("w"), Repo::Proj, &["commit", "-qam", "copy w.txt"]),
        Step::commit(&ww("w"), Repo::Proj, "w-proj"),
        stops_unparseable(
            Step::rwv(&ww("w"), &["sync", "--history", "linear"]),
            "the replay finished",
        )
        .claim(Claim::Contains {
            at: ww("w"),
            repo: Repo::App,
            rev: "HEAD",
            mark: "a-app",
        }),
    ]);
    steps.extend(aborted_to_the_workweaves_own(&ww("w"), &[Repo::App]));
    steps.push(
        Step::git(&ww("w"), Repo::App, &["log", "--format=%s", "-1"])
            .claim(Claim::OutputLacks("a-app")),
    );
    let (listed, unlisted, dir) = match change {
        TargetMembers::Adds => (LIB, DOCS, ".workweaves/proj--w/local/remotes/docs"),
        TargetMembers::Removes => (DOCS, LIB, ".workweaves/proj--w/local/remotes/lib"),
    };
    let checkout = match change {
        TargetMembers::Adds => Claim::DirGone(Machine::A, dir),
        TargetMembers::Removes => Claim::DirStands(Machine::A, dir),
    };
    let held = |file: &'static str| {
        let step =
            Step::git(&ww("w"), Repo::Proj, &["show", file]).claim(Claim::OutputContains(listed));
        match change {
            TargetMembers::Adds => step.claim(Claim::OutputLacks(unlisted)),
            TargetMembers::Removes => step.claim(Claim::OutputContains(unlisted)),
        }
    };
    steps.push(held("HEAD:rwv.toml").claim(checkout));
    steps.push(held("HEAD:rwv.lock"));
    scenario("abort restores members past an unparseable rwv.toml", steps)
}

/// A sync stops on an unparseable `rwv.toml` having fast-forwarded the
/// workweave's `lib` to `a`'s, and the operator's half-finished fix leaves a
/// working `rwv.toml` that parses but no longer lists `lib`. `rwv abort` still puts `lib` back at its
/// savepoint, keeping the half-finished fix in a backup.
pub fn abort_ignores_a_half_finished_manifest_fix() -> Scenario {
    let mut steps = vec![
        create("w"),
        Step::commit(&a(), Repo::Lib, "a-lib"),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
    ];
    steps.extend(adds_a_copies(&a()));
    steps.push(Step::commit(&a(), Repo::Proj, "a-proj"));
    steps.extend(adds_w_copies(&ww("w")));
    steps.push(Step::commit(&ww("w"), Repo::Proj, "w-proj"));
    steps.extend([
        stops_unparseable(
            Step::rwv(&ww("w"), &["sync", "--history", "linear"]),
            "the replay finished",
        )
        .claim(Claim::Contains {
            at: ww("w"),
            repo: Repo::Lib,
            rev: "HEAD",
            mark: "a-lib",
        }),
        Step::hand_edit(&ww("w"), Repo::Proj, "rwv.toml", W_COPIES, ""),
        Step::drop_manifest_entry(&ww("w"), Repo::Proj, Repo::Lib),
        Step::rwv(&ww("w"), &["abort"])
            .expect(Exit::Succeeds)
            .may_restore(&[Repo::Proj, Repo::Lib])
            .may_rewind(&[Repo::Lib])
            .claim(Claim::Lacks {
                at: ww("w"),
                repo: Repo::Proj,
                rev: "HEAD",
                mark: "a-proj",
            })
            .claim(Claim::Lacks {
                at: a(),
                repo: Repo::Proj,
                rev: "main",
                mark: "w-proj",
            }),
        Step::git(&ww("w"), Repo::Lib, &["log", "--format=%s", "-3"])
            .claim(Claim::OutputLacks("a-lib")),
        Step::git(&ww("w"), Repo::Proj, &["show", "HEAD:rwv.toml"])
            .claim(Claim::OutputContains(LIB))
            .claim(Claim::OutputLacks("a.txt")),
    ]);
    scenario("abort ignores a half-finished rwv.toml fix", steps)
}

/// A workweave branch whose middle commit holds an `rwv.toml` that does not
/// parse, and whose tip fixes it, is replayed onto a target that moved and
/// lands under linear history: only the result is read. The landed commit
/// that breaks the file stays as it is, and `rwv cherry-pick` of it, or of
/// the commit that fixes it, refuses naming the commit whose `rwv.toml`
/// does not parse, and moves nothing.
pub fn an_unparseable_intermediate_manifest_is_replayed() -> Scenario {
    let mut steps = vec![
        create("p"),
        create("w"),
        Step::commit(&a(), Repo::Proj, "a-proj"),
    ];
    steps.extend([
        Step::hand_edit(
            &ww("w"),
            Repo::Proj,
            "rwv.toml",
            UNDER_INTEGRATIONS,
            "enabled = false\n[[[\n",
        ),
        Step::git(&ww("w"), Repo::Proj, &["commit", "-qam", "break rwv.toml"]),
        Step::hand_edit(
            &ww("w"),
            Repo::Proj,
            "rwv.toml",
            "enabled = false\n[[[\n",
            UNDER_INTEGRATIONS,
        ),
        Step::git(&ww("w"), Repo::Proj, &["commit", "-qam", "fix rwv.toml"]),
        Step::rwv(&ww("w"), &["sync", "--history", "linear"]).expect(Exit::Succeeds),
        Step::commit(&a(), Repo::Proj, "a-proj-2"),
        Step::rwv(&ww("w"), &["land", "--history", "linear"]).expect(Exit::Succeeds),
        Step::git(&a(), Repo::Proj, &["log", "--format=%s", "-6", "main"])
            .claim(Claim::OutputInOrder(&["fix rwv.toml", "break rwv.toml"])),
    ]);
    for picked in ["main~1", "main"] {
        steps.push(
            Step::rwv(&ww("p"), &["cherry-pick", picked])
                .expect(Exit::refuses(Repo::Proj, State::UnparseableProjectCommit))
                .claim(Claim::OutputContains("[[["))
                .claim(Claim::LocalStateUnchanged(ww("p"))),
        );
    }
    scenario("an unparseable intermediate rwv.toml is replayed", steps)
}

/// What a replay stopped on a conflict holds in `rwv.toml` when the
/// operator resolves the conflict and continues.
#[derive(Clone, Copy)]
pub enum ReplayedManifest {
    /// The branch's own commits break `rwv.toml` and fix it two commits
    /// later, and the replay stopped on another file's conflict between
    /// them.
    BrokenByTheBranch,
    /// `rwv.toml` itself conflicted, resolved to a file that does not parse.
    BadlyResolved,
}

/// A replay stopped on a conflict, resolved and continued while the
/// replayed `rwv.toml` does not parse: the replay goes on and only its
/// result is read. A branch that fixes the file itself lands; a bad
/// resolution of the file stops once the replay has finished, and a staged
/// fix then finishes the operation.
pub fn a_replay_in_flight_is_not_judged_on_its_rwv_toml(
    taking_in: TakingIn,
    replayed: ReplayedManifest,
) -> Scenario {
    let broken = "enabled = false\n[[[\n";
    let mut steps = vec![Step::commit(&a(), Repo::Proj, "notes"), create("w")];
    let conflicted = match replayed {
        ReplayedManifest::BrokenByTheBranch => {
            steps.extend([
                Step::hand_edit(&a(), Repo::Proj, "notes.txt", "notes\n", "notes on a\n"),
                Step::git(&a(), Repo::Proj, &["commit", "-qam", "a notes"]),
                Step::hand_edit(&ww("w"), Repo::Proj, "rwv.toml", UNDER_INTEGRATIONS, broken),
                Step::git(&ww("w"), Repo::Proj, &["commit", "-qam", "break rwv.toml"]),
                Step::hand_edit(&ww("w"), Repo::Proj, "notes.txt", "notes\n", "notes in w\n"),
                Step::git(&ww("w"), Repo::Proj, &["commit", "-qam", "w notes"]),
                Step::hand_edit(&ww("w"), Repo::Proj, "rwv.toml", broken, UNDER_INTEGRATIONS),
                Step::git(&ww("w"), Repo::Proj, &["commit", "-qam", "fix rwv.toml"]),
            ]);
            "notes.txt"
        }
        ReplayedManifest::BadlyResolved => {
            steps.extend(adds_a_copies(&a()));
            steps.extend([
                Step::hand_edit(
                    &ww("w"),
                    Repo::Proj,
                    "rwv.toml",
                    UNDER_INTEGRATIONS,
                    "enabled = false\n\n[workweave]\ncopy = [\"w.txt\"]\n",
                ),
                Step::git(&ww("w"), Repo::Proj, &["commit", "-qam", "copy w.txt"]),
            ]);
            "rwv.toml"
        }
    };
    steps.extend([
        Step::rwv(&ww("w"), &taking_in.args())
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .claim(Claim::OutputContains("conflict"))
            .claim(Claim::OutputContains(taking_in.resume())),
        Step::git(&ww("w"), Repo::Proj, &["checkout", "--theirs", conflicted]),
    ]);
    if let ReplayedManifest::BadlyResolved = replayed {
        steps.push(Step::hand_edit(
            &ww("w"),
            Repo::Proj,
            "rwv.toml",
            "enabled = false\n",
            broken,
        ));
    }
    steps.push(Step::git(&ww("w"), Repo::Proj, &["add", conflicted]));
    let resume = Step::rwv(&ww("w"), &[taking_in.args()[0], "--continue"]);
    match replayed {
        ReplayedManifest::BrokenByTheBranch => {
            steps.push(resume.expect(Exit::Succeeds).may_strand(&[Repo::Proj]))
        }
        ReplayedManifest::BadlyResolved => steps.extend([
            resume
                .expect(Exit::refuses(
                    Repo::Proj,
                    State::UnparseableProjectMidOperation,
                ))
                .claim(Claim::OutputContains("the replay finished")),
            Step::git(&ww("w"), Repo::Proj, &["status"])
                .claim(Claim::OutputLacks("rebase in progress")),
            Step::hand_edit(
                &ww("w"),
                Repo::Proj,
                "rwv.toml",
                broken,
                "enabled = false\n",
            ),
            Step::rwv_printed(&ww("w"), "git -C ").expect(Exit::Succeeds),
            Step::rwv(&ww("w"), &[taking_in.args()[0], "--continue"])
                .expect(Exit::Succeeds)
                .may_strand(&[Repo::Proj]),
        ]),
    }
    steps.push(
        Step::git(&ww("w"), Repo::Proj, &["show", "HEAD:rwv.toml"])
            .claim(Claim::OutputLacks("[[["))
            .claim(Claim::OutputContains(match replayed {
                ReplayedManifest::BrokenByTheBranch => "enabled = false",
                ReplayedManifest::BadlyResolved => "w.txt",
            })),
    );
    if taking_in.lands() {
        steps.push(
            Step::git(&a(), Repo::Proj, &["show", "main:rwv.toml"])
                .claim(Claim::OutputLacks("[[[")),
        );
    }
    scenario("a replay in flight is not judged on its rwv.toml", steps)
}

/// What is run once a `--continue` that would carry a staged `rwv.toml`
/// into the replayed tip was killed or refused.
#[derive(Clone, Copy)]
pub enum ThenRun {
    Continue,
    Abort,
}

/// [`unparseable_merged_manifest`]'s stop under linear history, reached by
/// `taking_in` over a `lib` that each side moved and locked, so the replayed
/// lock commit is re-pinned; with the workweave's table dropped and the fix
/// staged by the stop's printed line.
fn a_fix_staged_at_the_replayed_tip(taking_in: TakingIn) -> Vec<Step> {
    let mut steps = vec![
        create("w"),
        Step::commit(&a(), Repo::Lib, "a-lib"),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::commit(&ww("w"), Repo::Lib, "w-lib"),
        Step::rwv(&ww("w"), &["lock", "--commit"]).expect(Exit::Succeeds),
    ];
    steps.extend(adds_a_copies(&a()));
    steps.push(Step::commit(&a(), Repo::Proj, "a-proj"));
    steps.extend([
        Step::hand_edit(
            &ww("w"),
            Repo::Proj,
            "rwv.toml",
            ABOVE_DOCS,
            "\n[workweave]\ncopy = [\"w.txt\"]\n\n[repositories.\"local/remotes/docs\"]",
        ),
        Step::git(&ww("w"), Repo::Proj, &["add", "rwv.toml"]),
        Step::commit(&ww("w"), Repo::Proj, "w-proj"),
        stops_unparseable(Step::rwv(&ww("w"), &taking_in.args()), taking_in.says())
            .may_rewind(&[Repo::Lib]),
        Step::hand_edit(&ww("w"), Repo::Proj, "rwv.toml", W_COPIES, ""),
        Step::rwv_printed(&ww("w"), "git -C ").expect(Exit::Succeeds),
    ]);
    steps
}

/// The workweave's `w-proj` holds the staged fix and `a`'s table, with no
/// `rwv.toml` that does not parse left at its tip or on `a`'s `main`.
fn the_fix_is_in_the_tip(taking_in: TakingIn) -> Vec<Step> {
    let mut steps = vec![
        Step::git(&ww("w"), Repo::Proj, &["log", "--format=%s", "-1"])
            .claim(Claim::OutputLine("w-proj")),
        Step::git(&ww("w"), Repo::Proj, &["show", "HEAD:rwv.toml"])
            .claim(Claim::OutputContains(A_COPIES))
            .claim(Claim::OutputLacks("w.txt")),
    ];
    if taking_in.lands() {
        steps.push(
            Step::git(&a(), Repo::Proj, &["show", "main:rwv.toml"])
                .claim(Claim::OutputContains(A_COPIES))
                .claim(Claim::OutputLacks("w.txt")),
        );
    }
    steps
}

/// [`a_fix_staged_at_the_replayed_tip`], its `--continue` killed at `point`:
/// at the re-map's record, before the branch moves to the copy of the
/// replayed tip that holds the fix, or after it moved, the tip then holding
/// the fix. Run again, the `--continue` finishes with the fix in the tip;
/// `rwv abort` puts the workweave back, keeping the fix as a backup whose
/// printed show line returns it: still uncommitted before the move, and in
/// the replayed tip after a sync's move, until its relock.
pub fn a_carried_fix_killed_part_way(
    taking_in: TakingIn,
    point: &'static str,
    then: ThenRun,
) -> Scenario {
    let mut steps = a_fix_staged_at_the_replayed_tip(taking_in);
    steps.extend([
        Step::rwv_paused(
            &ww("w"),
            &[taking_in.args()[0], "--continue"],
            point,
            "carrying",
        ),
        Step::kill("carrying"),
    ]);
    if point != "remap-recorded" {
        steps.push(
            Step::git(&ww("w"), Repo::Proj, &["show", "HEAD:rwv.toml"])
                .claim(Claim::OutputContains(A_COPIES))
                .claim(Claim::OutputLacks("w.txt")),
        );
    }
    match then {
        ThenRun::Continue => {
            steps.push(
                Step::rwv(&ww("w"), &[taking_in.args()[0], "--continue"])
                    .expect(Exit::Succeeds)
                    .may_strand(&[Repo::Proj]),
            );
            steps.extend(the_fix_is_in_the_tip(taking_in));
        }
        ThenRun::Abort => {
            let abort = Step::rwv(&ww("w"), &["abort"]).may_strand(&[Repo::Proj]);
            steps.extend(aborted_from(
                match point {
                    "remap-recorded" => abort.claim(Claim::OutputContains(
                        "what abort discarded is kept as backup",
                    )),
                    "remap-moved" => abort.claim(Claim::OutputContains(
                        "projects/proj: what abort discarded is kept as backup",
                    )),
                    _ => abort,
                },
                &ww("w"),
                &[Repo::Lib],
            ));
            match point {
                "remap-recorded" => steps.push(kept_backup_shown(
                    &ww("w"),
                    "projects/proj log ",
                    "rwv.toml",
                )),
                "remap-moved" => {
                    steps.push(kept_backup_shown(&ww("w"), "projects/proj log ", "+w-proj"))
                }
                _ => {}
            }
        }
    }
    scenario("a carried fix killed part way", steps)
}

/// [`a_fix_staged_at_the_replayed_tip`] with an edit to `rwv.lock` left
/// beside the fix: the copy of the replayed tip rewrites the lock, so the
/// `--continue` refuses in the same state, saying so, before anything moves.
/// With the edit undone it finishes; or the printed `rwv abort` puts the
/// workweave back, keeping both edits as a backup.
pub fn a_carried_fix_beside_an_edited_lock(taking_in: TakingIn, then: ThenRun) -> Scenario {
    let mut steps = a_fix_staged_at_the_replayed_tip(taking_in);
    steps.extend([
        Step::hand_edit(
            &ww("w"),
            Repo::Proj,
            "rwv.lock",
            "\"repositories\"",
            "\"repositories\" ",
        ),
        Step::rwv(&ww("w"), &[taking_in.args()[0], "--continue"])
            .expect(Exit::refuses(
                Repo::Proj,
                State::UnparseableProjectMidOperation,
            ))
            .claim(Claim::OutputContains("rwv.lock has uncommitted edits"))
            .claim(Claim::LocalStateUnchanged(ww("w"))),
    ]);
    match then {
        ThenRun::Continue => {
            steps.extend([
                Step::hand_edit(
                    &ww("w"),
                    Repo::Proj,
                    "rwv.lock",
                    "\"repositories\" ",
                    "\"repositories\"",
                ),
                Step::rwv_printed(&ww("w"), taking_in.resume())
                    .expect(Exit::Succeeds)
                    .may_strand(&[Repo::Proj]),
            ]);
            steps.extend(the_fix_is_in_the_tip(taking_in));
        }
        ThenRun::Abort => steps.extend(aborted_from(
            Step::rwv_printed(&ww("w"), "rwv abort").claim(Claim::OutputContains(
                "what abort discarded is kept as backup",
            )),
            &ww("w"),
            &[Repo::Lib],
        )),
    }
    scenario("a carried fix beside an edited lock", steps)
}

/// [`a_fix_staged_at_the_replayed_tip`] with an edit to another file staged
/// beside the fix: the `--continue` carries only `rwv.toml` into the
/// replayed tip, and the other edit stays staged.
pub fn another_staged_edit_stays_staged_past_a_carried_fix(taking_in: TakingIn) -> Scenario {
    let mut steps = a_fix_staged_at_the_replayed_tip(taking_in);
    steps.extend([
        Step::hand_edit(
            &ww("w"),
            Repo::Proj,
            "w-proj.txt",
            "w-proj\n",
            "w-proj, staged\n",
        ),
        Step::git(&ww("w"), Repo::Proj, &["add", "w-proj.txt"]),
        Step::rwv(&ww("w"), &[taking_in.args()[0], "--continue"])
            .expect(Exit::Succeeds)
            .may_strand(&[Repo::Proj]),
        Step::git(&ww("w"), Repo::Proj, &["diff", "--cached", "--name-only"])
            .claim(Claim::OutputLine("w-proj.txt")),
        Step::git(&ww("w"), Repo::Proj, &["show", "HEAD:w-proj.txt"])
            .claim(Claim::OutputLine("w-proj")),
    ]);
    steps.extend(the_fix_is_in_the_tip(taking_in));
    scenario("another staged edit stays staged past a carried fix", steps)
}

/// A landing that stopped on a conflict in `app` after its project replay
/// took in `a`'s added `docs`, with the working `rwv.toml` then broken by
/// hand: the project repo is stopped in nothing, so `rwv abort` reads the
/// members it restores at the savepoint, which does not list `docs`, not at
/// the replayed tip, which does, and finds no member without a savepoint.
pub fn abort_reads_the_savepoint_past_a_broken_working_rwv_toml() -> Scenario {
    let steps = vec![
        Step::rwv(&a(), &["member", "remove", DOCS]).expect(Exit::Succeeds),
        create("w"),
        Step::rwv(&a(), &["member", "add", "url:origin:docs"]).expect(Exit::Succeeds),
        Step::hand_edit(&a(), Repo::App, "README", "app", "alpha"),
        Step::git(&a(), Repo::App, &["commit", "-qam", "alpha"]),
        Step::rwv(&a(), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::hand_edit(&ww("w"), Repo::App, "README", "app", "beta"),
        Step::git(&ww("w"), Repo::App, &["commit", "-qam", "beta"]),
        Step::rwv(&ww("w"), &["lock", "--commit"]).expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &["land", "--history", "linear"])
            .expect(Exit::refuses_kind(RefusalKind::OpParked))
            .may_rewind(&[Repo::App])
            .claim(Claim::OutputContains("local/remotes/app")),
        Step::git(&ww("w"), Repo::Proj, &["show", "HEAD:rwv.toml"])
            .claim(Claim::OutputContains(DOCS))
            .claim(Claim::DirStands(
                Machine::A,
                ".workweaves/proj--w/local/remotes/docs",
            )),
        Step::hand_edit(
            &ww("w"),
            Repo::Proj,
            "rwv.toml",
            UNDER_INTEGRATIONS,
            "enabled = false\n[[[\n",
        ),
        Step::rwv(&ww("w"), &["abort"])
            .expect(Exit::Succeeds)
            .may_restore(&[Repo::Proj, Repo::App])
            .may_rewind(&[Repo::App])
            .claim(Claim::OutputLacks(DOCS))
            .claim(Claim::OutputLacks("no savepoint")),
        Step::git(&ww("w"), Repo::Proj, &["show", "HEAD:rwv.toml"]).claim(Claim::OutputLacks(DOCS)),
    ];
    scenario(
        "abort reads the savepoint past a broken working rwv.toml",
        steps,
    )
}

/// How the checkout is moved off the replayed tip by hand before the
/// `--continue`.
#[derive(Clone, Copy)]
pub enum OffTheReplayedTip {
    /// A commit made on top of the replayed tip, the fix left staged.
    CommitOnTop,
    /// Another branch made and checked out at the replayed tip.
    AnotherBranch,
    /// HEAD detached at the replayed tip.
    Detached,
}

/// [`a_fix_staged_at_the_replayed_tip`] with the checkout moved off the
/// replayed tip by `moved`: the staged fix is carried only into the commit
/// the replay wrote, on the branch it wrote, so the `--continue` refuses in
/// the same state, naming what stands in the way, and moves nothing. A
/// commit made on top is the operator's, which `rwv abort` refuses to
/// discard: moved off by hand, the `--continue` finishes with the fix in the
/// replayed tip. Otherwise the printed `rwv abort` puts the workweave back
/// with no `--abandon-foreign-tip`, keeping the fix as a backup.
pub fn a_fix_is_not_carried_off_the_replayed_tip(
    taking_in: TakingIn,
    moved: OffTheReplayedTip,
) -> Scenario {
    let mut steps = a_fix_staged_at_the_replayed_tip(taking_in);
    let (args, says): (&[&str], &'static str) = match moved {
        OffTheReplayedTip::CommitOnTop => (
            &["commit", "-q", "--only", "--allow-empty", "-m", "hand"],
            "a commit made after the replay",
        ),
        OffTheReplayedTip::AnotherBranch => (
            &["checkout", "-q", "-b", "side"],
            "the branch the replay wrote",
        ),
        OffTheReplayedTip::Detached => (&["checkout", "-q", "--detach"], "HEAD is detached"),
    };
    steps.extend([
        Step::git(&ww("w"), Repo::Proj, args),
        Step::rwv(&ww("w"), &[taking_in.args()[0], "--continue"])
            .expect(Exit::refuses(
                Repo::Proj,
                State::UnparseableProjectMidOperation,
            ))
            .claim(Claim::OutputContains(says))
            .claim(Claim::LocalStateUnchanged(ww("w")))
            .claim(Claim::Lacks {
                at: a(),
                repo: Repo::Proj,
                rev: "main",
                mark: "w-proj",
            }),
    ]);
    if let OffTheReplayedTip::CommitOnTop = moved {
        steps.extend([
            Step::git(&ww("w"), Repo::Proj, &["reset", "-q", "--soft", "HEAD~1"]),
            Step::rwv_printed(&ww("w"), taking_in.resume())
                .expect(Exit::Succeeds)
                .may_strand(&[Repo::Proj]),
        ]);
        steps.extend(the_fix_is_in_the_tip(taking_in));
        return scenario("a fix is not carried off the replayed tip", steps);
    }
    steps.extend([
        Step::rwv_printed(&ww("w"), "rwv abort")
            .expect(Exit::Succeeds)
            .may_restore(&[Repo::Proj, Repo::Lib])
            .may_rewind(&[Repo::Lib])
            .claim(Claim::OutputContains(
                "what abort discarded is kept as backup",
            ))
            .claim(Claim::Lacks {
                at: ww("w"),
                repo: Repo::Proj,
                rev: "HEAD",
                mark: "a-proj",
            })
            .claim(Claim::Lacks {
                at: a(),
                repo: Repo::Proj,
                rev: "main",
                mark: "w-proj",
            }),
        Step::git(&ww("w"), Repo::Proj, &["show", "HEAD:rwv.toml"])
            .claim(Claim::OutputContains("w.txt"))
            .claim(Claim::OutputLacks("a.txt")),
    ]);
    scenario("a fix is not carried off the replayed tip", steps)
}

/// [`unparseable_merged_manifest`] under linear history where the
/// workweave's one project commit adds its table and nothing else: the
/// staged fix that drops the table leaves the replayed tip changing nothing,
/// so the `--continue` drops it, as a rebase drops a commit it leaves empty,
/// and says so.
pub fn a_fix_that_empties_the_replayed_tip_drops_it(taking_in: TakingIn) -> Scenario {
    let mut steps = vec![create("w")];
    steps.extend(adds_a_copies(&a()));
    steps.push(Step::commit(&a(), Repo::Proj, "a-proj"));
    steps.extend(adds_w_copies(&ww("w")));
    steps.extend([
        Step::rwv(&ww("w"), &taking_in.args()).expect(Exit::refuses(
            Repo::Proj,
            State::UnparseableProjectMidOperation,
        )),
        Step::hand_edit(&ww("w"), Repo::Proj, "rwv.toml", W_COPIES, ""),
        Step::rwv_printed(&ww("w"), "git -C ").expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &[taking_in.args()[0], "--continue"])
            .expect(Exit::Succeeds)
            .may_strand(&[Repo::Proj])
            .claim(Claim::OutputContains(
                "is dropped: with the resolved rwv.toml it changes nothing",
            )),
        Step::git(&ww("w"), Repo::Proj, &["log", "--format=%s", "-3"])
            .claim(Claim::OutputLacks("copy w.txt"))
            .claim(Claim::OutputContains("a-proj")),
        Step::git(&ww("w"), Repo::Proj, &["status", "--porcelain"])
            .claim(Claim::OutputLacks("rwv.toml")),
    ]);
    scenario("a fix that empties the replayed tip drops it", steps)
}

/// [`unparseable_merged_manifest`] under linear history over a workweave
/// branch of three project commits, the first adding its table, so every
/// replayed commit holds an `rwv.toml` that does not parse. The stop says the
/// two earlier ones keep it; a staged fix goes into the tip alone, and once
/// landed `rwv cherry-pick`, `rwv switch --detach` and `rwv workweave create`
/// at an earlier one refuse it by name, moving and making nothing.
pub fn earlier_replayed_commits_keep_an_unparseable_rwv_toml(taking_in: TakingIn) -> Scenario {
    let mut steps = vec![create("p"), create("w")];
    steps.extend(adds_a_copies(&a()));
    steps.push(Step::commit(&a(), Repo::Proj, "a-proj"));
    steps.extend(adds_w_copies(&ww("w")));
    steps.extend([
        Step::commit(&ww("w"), Repo::Proj, "more"),
        Step::commit(&ww("w"), Repo::Proj, "w-proj"),
        stops_unparseable(Step::rwv(&ww("w"), &taking_in.args()), taking_in.says())
            .claim(Claim::OutputContains("2 earlier replayed commits keep")),
        Step::hand_edit(&ww("w"), Repo::Proj, "rwv.toml", W_COPIES, ""),
        Step::rwv_printed(&ww("w"), "git -C ").expect(Exit::Succeeds),
        Step::rwv(&ww("w"), &[taking_in.args()[0], "--continue"])
            .expect(Exit::Succeeds)
            .may_strand(&[Repo::Proj]),
    ]);
    steps.extend(the_fix_is_in_the_tip(taking_in));
    steps.push(
        Step::git(&ww("w"), Repo::Proj, &["show", "HEAD~1:rwv.toml"])
            .claim(Claim::OutputContains("w.txt")),
    );
    if taking_in.lands() {
        steps.extend([
            Step::rwv(&ww("p"), &["cherry-pick", "main~1"])
                .expect(Exit::refuses(Repo::Proj, State::UnparseableProjectCommit))
                .claim(Claim::LocalStateUnchanged(ww("p"))),
            Step::rwv(&a(), &["workweave", "create", "w3", "--at", "main~1"])
                .expect(Exit::refuses(Repo::Proj, State::UnparseableProjectCommit))
                .claim(Claim::OutputContains("duplicate key"))
                .claim(Claim::LocalStateUnchanged(a())),
            Step::rwv(&a(), &["workweave", "create", "w4", "--detach", "main~1"])
                .expect(Exit::refuses(Repo::Proj, State::UnparseableProjectCommit))
                .claim(Claim::OutputContains("duplicate key"))
                .claim(Claim::LocalStateUnchanged(a())),
            Step::rwv(&a(), &["switch", "--detach", "main~1"])
                .expect(Exit::refuses(Repo::Proj, State::UnparseableProjectCommit))
                .claim(Claim::OutputContains("duplicate key"))
                .claim(Claim::LocalStateUnchanged(a())),
        ]);
    }
    scenario(
        "earlier replayed commits keep an unparseable rwv.toml",
        steps,
    )
}

/// [`unparseable_merged_manifest`] under merge history, with `a` adding a
/// file the workweave's project repo holds untracked: the merge that would
/// stop on the unparseable `rwv.toml` is not started over it. The sync
/// refuses naming the file and leaves the workweave as it was; with the file
/// moved aside, the printed `--continue` stops on the unparseable merge and
/// abort ends it.
pub fn an_untracked_file_in_the_way_of_the_merge_is_named() -> Scenario {
    let mut steps = vec![
        create("w"),
        Step::commit(&ww("w"), Repo::Proj, "new"),
        Step::git(&a(), Repo::Proj, &["checkout", "proj--w", "--", "new.txt"]),
        Step::git(&a(), Repo::Proj, &["commit", "-qm", "a adds new.txt"]),
        Step::git(&ww("w"), Repo::Proj, &["reset", "-q", "HEAD~1"]).may_strand(&[Repo::Proj]),
    ];
    steps.extend(adds_a_copies(&a()));
    steps.push(Step::commit(&a(), Repo::Proj, "a-proj"));
    steps.extend(adds_w_copies(&ww("w")));
    steps.push(Step::commit(&ww("w"), Repo::Proj, "w-proj"));
    steps.extend([
        Step::rwv(&ww("w"), &["sync", "--history", "merge"])
            .expect(Exit::refuses_kind(RefusalKind::UntrackedCollision))
            .claim(Claim::OutputContains("new.txt"))
            .claim(Claim::OutputContains("rwv sync --continue"))
            .claim(Claim::LocalStateUnchanged(ww("w"))),
        Step::git(&ww("w"), Repo::Proj, &["clean", "-fq", "--", "new.txt"]),
        stops_unparseable(
            Step::rwv(&ww("w"), &["sync", "--continue"]),
            "the merge is in progress",
        ),
    ]);
    steps.extend(aborted_to_the_workweaves_own(&ww("w"), &[]));
    scenario("an untracked file in the way of the merge is named", steps)
}

/// [`unparseable_merged_manifest`] stopped by `taking_in`, and `rwv.toml`
/// removed from the project repo with `git rm`: `--continue` stops in the
/// same state, and the printed `rwv abort` puts the workweave back.
pub fn a_removed_rwv_toml_stops_as_unparseable(taking_in: TakingIn) -> Scenario {
    let mut steps = vec![create("w")];
    steps.extend(adds_a_copies(&a()));
    steps.push(Step::commit(&a(), Repo::Proj, "a-proj"));
    steps.extend(adds_w_copies(&ww("w")));
    steps.push(Step::commit(&ww("w"), Repo::Proj, "w-proj"));
    steps.extend([
        stops_unparseable(Step::rwv(&ww("w"), &taking_in.args()), taking_in.says()),
        Step::git(&ww("w"), Repo::Proj, &["rm", "-q", "--cached", "rwv.toml"]),
        Step::git(&ww("w"), Repo::Proj, &["clean", "-fq", "--", "rwv.toml"]),
        Step::rwv(&ww("w"), &[taking_in.args()[0], "--continue"])
            .expect(Exit::refuses(
                Repo::Proj,
                State::UnparseableProjectMidOperation,
            ))
            .claim(Claim::LocalStateUnchanged(ww("w")))
            .claim(if taking_in.linear() {
                Claim::OutputContains("the replayed tip's rwv.toml does not parse")
            } else {
                Claim::OutputLacks("rwv.toml does not parse")
            }),
    ]);
    steps.extend(aborted_from(Step::rwv(&ww("w"), &["abort"]), &ww("w"), &[]));
    scenario("a removed rwv.toml stops as unparseable", steps)
}
